INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_math_u1_L02_basic#1','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','안내판에 「12세 이상 관람 가」라고 적혀 있어요. 딱 12세인 친구는 어떻게 될까요?',ARRAY['M5-2-u1-X01','M5-2-u1-X17']::text[],true,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"안내판에 「12세 이상 관람 가」라고 적혀 있어요. 딱 12세인 친구는 어떻게 될까요?","options":[{"t":"볼 수 있다","correct":true},{"t":"볼 수 없다","mis":"M5-2-u1-X01"},{"t":"13세부터만 볼 수 있다","mis":"M5-2-u1-X01"},{"t":"보호자가 있어야만 볼 수 있다","mis":"M5-2-u1-X17"}],"explanation":["12세 이상은 12세와 같거나 많은 나이를 뜻해요.","경곗값 12세가 들어가요.","그래서 딱 12세인 친구는 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"안내판에 「15세 이상 관람 가」라고 적혀 있어요. 딱 15세인 친구는 어떻게 될까요?","options":[{"t":"볼 수 있다","correct":true},{"t":"볼 수 없다","mis":"M5-2-u1-X01"},{"t":"16세부터만 볼 수 있다","mis":"M5-2-u1-X01"},{"t":"보호자가 있어야만 볼 수 있다","mis":"M5-2-u1-X17"}],"explanation":["15세 이상은 15세와 같거나 많은 나이를 뜻해요.","경곗값 15세가 들어가요.","그래서 딱 15세인 친구는 볼 수 있어요."]},{"stem":"안내판에 「8세 이상 탑승 가」라고 적혀 있어요. 딱 8세인 친구는 어떻게 될까요?","options":[{"t":"탈 수 있다","correct":true},{"t":"탈 수 없다","mis":"M5-2-u1-X01"},{"t":"9세부터만 탈 수 있다","mis":"M5-2-u1-X01"},{"t":"보호자가 있어야만 탈 수 있다","mis":"M5-2-u1-X17"}],"explanation":["8세 이상은 8세와 같거나 많은 나이를 뜻해요.","경곗값 8세가 들어가요.","그래서 딱 8세인 친구는 탈 수 있어요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#2','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','2 이상인 수를 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03']::text[],true,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"2 이상인 수를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"2와 같거나 큰 수","correct":true},{"t":"2보다 큰 수","mis":"M5-2-u1-X01"},{"t":"2와 같거나 작은 수","mis":"M5-2-u1-X03"},{"t":"2보다 작은 수","mis":"M5-2-u1-X03"}],"explanation":["이상은 「그 수와 같거나 큰 수」라는 뜻이에요.","2 이상인 수에는 2가 들어가요.","수직선에는 2에 ●으로 나타내요."],"variant_rule":{"alt":[{"stem":"3 이하인 수를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"3과 같거나 작은 수","correct":true},{"t":"3보다 작은 수","mis":"M5-2-u1-X01"},{"t":"3과 같거나 큰 수","mis":"M5-2-u1-X03"},{"t":"3보다 큰 수","mis":"M5-2-u1-X03"}],"explanation":["이하는 「그 수와 같거나 작은 수」라는 뜻이에요.","3 이하인 수에는 3이 들어가요.","수직선에는 3에 ●으로 나타내요."]},{"stem":"30 이상인 수를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"30과 같거나 큰 수","correct":true},{"t":"30보다 큰 수","mis":"M5-2-u1-X01"},{"t":"30과 같거나 작은 수","mis":"M5-2-u1-X03"},{"t":"30보다 작은 수","mis":"M5-2-u1-X03"}],"explanation":["이상은 「그 수와 같거나 큰 수」라는 뜻이에요.","30 이상인 수에는 30이 들어가요.","수직선에는 30에 ●으로 나타내요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#3','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'sa','auto','28, 30, 35.5, 29.9, 41, 30.1 중에서 30 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C1","difficulty":1,"kind":"sa","stem":"28, 30, 35.5, 29.9, 41, 30.1 중에서 30 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["30 이상인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 30, 35.5, 41, 30.1이에요.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"24, 25.1, 19, 23.9, 30, 24.5 중에서 24 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["24 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 24, 19, 23.9예요.","모두 3개예요."]},{"stem":"49.9, 50, 62, 47, 50.5 중에서 50 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["50 이상인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 50, 62, 50.5예요.","모두 3개예요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#4','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','수직선에 13에 ●이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],true,'{"seq":4,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"수직선에 13에 ●이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"13 이하인 수","correct":true},{"t":"13 미만인 수","mis":"M5-2-u1-X04"},{"t":"13 이상인 수","mis":"M5-2-u1-X03"},{"t":"13 초과인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","13은 ●이라 포함해요.","그래서 13 이하인 수예요."],"variant_rule":{"alt":[{"stem":"수직선에 27에 ●이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"27 이상인 수","correct":true},{"t":"27 초과인 수","mis":"M5-2-u1-X04"},{"t":"27 이하인 수","mis":"M5-2-u1-X03"},{"t":"27 미만인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","27은 ●이라 포함해요.","그래서 27 이상인 수예요."]},{"stem":"수직선에 40에 ●이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"40 이하인 수","correct":true},{"t":"40 미만인 수","mis":"M5-2-u1-X04"},{"t":"40 이상인 수","mis":"M5-2-u1-X03"},{"t":"40 초과인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","40은 ●이라 포함해요.","그래서 40 이하인 수예요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#5','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'sa','auto','27 이하인 수 중에서 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"27 이하인 수 중에서 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["27 이하인 수의 끝은 27이에요.","27은 들어가요.","그래서 가장 큰 자연수는 27이에요."],"variant_rule":{"alt":[{"stem":"45 이상인 수 중에서 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["45 이상인 수의 끝은 45예요.","45는 들어가요.","그래서 가장 작은 자연수는 45예요."]},{"stem":"63 이하인 수 중에서 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["63"],"explanation":["63 이하인 수의 끝은 63이에요.","63은 들어가요.","그래서 가장 큰 자연수는 63이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#6','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'mc','auto','사과주스 2 L, 1.9 L, 2.1 L, 2.8 L 중에서 2 L 이상이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X17']::text[],true,'{"seq":6,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"사과주스 2 L, 1.9 L, 2.1 L, 2.8 L 중에서 2 L 이상이 아닌 것은 어느 것인가요?","options":[{"t":"1.9 L","correct":true},{"t":"2 L","mis":"M5-2-u1-X01"},{"t":"2.1 L","mis":"M5-2-u1-X17"},{"t":"2.8 L","mis":"M5-2-u1-X17"}],"explanation":["2 L 이상은 경곗값을 포함해요.","1.9 L만 범위에서 벗어나요.","그래서 아닌 것은 1.9 L예요."],"variant_rule":{"alt":[{"stem":"세탁 세제 2.7 L, 3 L, 3.2 L, 2.5 L 중에서 3 L 이하가 아닌 것은 어느 것인가요?","options":[{"t":"3.2 L","correct":true},{"t":"2.7 L","mis":"M5-2-u1-X17"},{"t":"3 L","mis":"M5-2-u1-X01"},{"t":"2.5 L","mis":"M5-2-u1-X17"}],"explanation":["3 L 이하는 경곗값을 포함해요.","3.2 L만 범위에서 벗어나요.","그래서 아닌 것은 3.2 L예요."]},{"stem":"밀가루 1 kg, 0.8 kg, 1.5 kg, 1.2 kg 중에서 1 kg 이상이 아닌 것은 어느 것인가요?","options":[{"t":"0.8 kg","correct":true},{"t":"1 kg","mis":"M5-2-u1-X01"},{"t":"1.5 kg","mis":"M5-2-u1-X17"},{"t":"1.2 kg","mis":"M5-2-u1-X17"}],"explanation":["1 kg 이상은 경곗값을 포함해요.","0.8 kg만 범위에서 벗어나요.","그래서 아닌 것은 0.8 kg이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#7','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'mc','auto','50 m 달리기 기록이 준후 9.5초, 지아 8.7초, 미나 9초, 서윤 10.2초예요. 기록이 9초 이하인 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"50 m 달리기 기록이 준후 9.5초, 지아 8.7초, 미나 9초, 서윤 10.2초예요. 기록이 9초 이하인 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지아, 미나","correct":true},{"t":"지아","mis":"M5-2-u1-X01"},{"t":"준후, 서윤","mis":"M5-2-u1-X03"},{"t":"준후, 지아, 미나","mis":"M5-2-u1-X16"}],"explanation":["9초 이하는 9초와 같거나 짧은 기록이에요.","8.7초는 9초보다 짧고, 9초는 딱 9초라 들어가요.","9.5초·10.2초는 9초보다 길어 빠져요 — 지아, 미나예요."],"variant_rule":{"alt":[{"stem":"줄넘기 기록이 하람 48회, 도윤 50회, 세아 53회, 지후 47회예요. 기록이 50회 이상인 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"도윤, 세아","correct":true},{"t":"세아","mis":"M5-2-u1-X01"},{"t":"하람, 지후","mis":"M5-2-u1-X03"},{"t":"하람, 도윤, 세아","mis":"M5-2-u1-X16"}],"explanation":["50회 이상은 50회와 같거나 많은 기록이에요.","50회는 딱 50회라 들어가고 53회도 들어가요.","48회·47회는 50보다 적어 빠져요 — 도윤, 세아예요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#8','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'sa','auto','선거일 기준 18세 이상인 국민은 투표할 수 있어요. 연주네 가족은 할머니 68세, 아빠 45세, 엄마 43세, 언니 18세, 연주 11세예요. 투표할 수 있는 사람은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"선거일 기준 18세 이상인 국민은 투표할 수 있어요. 연주네 가족은 할머니 68세, 아빠 45세, 엄마 43세, 언니 18세, 연주 11세예요. 투표할 수 있는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["4","4명"],"explanation":["18세 이상은 18세와 같거나 많은 나이예요.","할머니·아빠·엄마는 18세보다 많고, 언니는 딱 18세라 들어가요.","연주만 빠지니 4명이에요."],"variant_rule":{"alt":[{"stem":"어린이 도서관은 13세 이하만 들어갈 수 있어요. 형 15세, 누나 13세, 나 11세, 동생 7세, 사촌 14세 중에서 들어갈 수 있는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["3","3명"],"explanation":["13세 이하는 13세와 같거나 적은 나이예요.","누나는 딱 13세라 들어가고 나·동생도 들어가요.","형·사촌은 빠지니 3명이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#9','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'ox','auto','15 이상인 수에는 15가 들어가지 않아요.',ARRAY['M5-2-u1-X01']::text[],true,'{"seq":9,"concept":"M5-2-u1-C1","difficulty":2,"kind":"ox","stem":"15 이상인 수에는 15가 들어가지 않아요.","answer":"X","reason_options":[{"t":"이상은 「같거나 크다」는 뜻이라 15도 들어가서","correct":true},{"t":"이상은 15보다 큰 수만 뜻해서","mis":"M5-2-u1-X01"}],"mis":"M5-2-u1-X01","explanation":["이상의 뜻에는 「같거나」가 들어 있어요.","그래서 15 이상인 수에는 15 자신이 들어가요.","수직선에도 15에 속이 찬 ●으로 그려요."],"variant_rule":{"alt":[{"stem":"40 이하인 수에는 40이 들어가요.","answer":"O","reason_options":[{"t":"이하는 「같거나 작다」는 뜻이라 40도 들어가서","correct":true},{"t":"이하는 40보다 작은 수만 뜻해서","mis":"M5-2-u1-X01"}],"explanation":["이하의 뜻에도 「같거나」가 들어 있어요.","그래서 40 이하인 수에는 40이 들어가요.","수직선에 40을 ●으로 그려요."]}]}}'::jsonb),
('g5_2_math_u1_L02_basic#10','math',5,2,'u1','L02','g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',3,'mc','auto','24.5, 23.9, 24, 25, 19 중에서 24 이하인 수를 모두 찾았어요. 그중 가장 큰 수는 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03']::text[],true,'{"seq":10,"concept":"M5-2-u1-C1","difficulty":3,"kind":"mc","stem":"24.5, 23.9, 24, 25, 19 중에서 24 이하인 수를 모두 찾았어요. 그중 가장 큰 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"23.9","mis":"M5-2-u1-X01"},{"t":"24.5","mis":"M5-2-u1-X03"},{"t":"25","mis":"M5-2-u1-X03"}],"explanation":["24 이하인 수는 24와 같거나 작은 수 — 23.9, 24, 19예요.","24.5와 25는 24보다 커서 빠져요.","들어간 수 가운데 가장 큰 수는 24예요."],"variant_rule":{"alt":[{"stem":"31, 29.8, 30, 30.2, 36 중에서 30 이상인 수를 모두 찾았어요. 그중 가장 작은 수는 어느 것인가요?","options":[{"t":"30","correct":true},{"t":"30.2","mis":"M5-2-u1-X01"},{"t":"29.8","mis":"M5-2-u1-X03"},{"t":"31","mis":"M5-2-u1-X16"}],"explanation":["30 이상인 수는 30, 30.2, 31, 36이에요.","29.8은 30보다 작아 빠져요.","들어간 수 가운데 가장 작은 수는 30이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#1','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',2,'mc','auto','㉠ 2.7 ㉡ 4.1 ㉢ 3.75 ㉣ 4 중에서 4보다 작은 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"㉠ 2.7 ㉡ 4.1 ㉢ 3.75 ㉣ 4 중에서 4보다 작은 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉢, ㉣","mis":"M5-2-u1-X02"},{"t":"㉡, ㉣","mis":"M5-2-u1-X03"},{"t":"㉢","mis":"M5-2-u1-X16"}],"explanation":["4보다 작은 수에는 4 자신이 들어가지 않아요.","2.7과 3.75는 4보다 작고, 4.1은 4보다 커요.","그래서 ㉠, ㉢이에요."],"variant_rule":{"alt":[{"stem":"㉠ 5.2 ㉡ 4.9 ㉢ 5 ㉣ 6.1 중에서 5보다 큰 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉣","correct":true},{"t":"㉠, ㉢, ㉣","mis":"M5-2-u1-X02"},{"t":"㉡","mis":"M5-2-u1-X03"},{"t":"㉣","mis":"M5-2-u1-X16"}],"explanation":["5보다 큰 수에는 5가 들어가지 않아요.","5.2와 6.1은 5보다 커요.","그래서 ㉠, ㉣이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#2','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',2,'mc','auto','「10 이상인 수」와 「10 이하인 수」에 함께 들어가는 수는 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X05']::text[],false,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「10 이상인 수」와 「10 이하인 수」에 함께 들어가는 수는 어느 것인가요?","options":[{"t":"10 하나뿐이다","correct":true},{"t":"없다","mis":"M5-2-u1-X01"},{"t":"9, 10, 11","mis":"M5-2-u1-X03"},{"t":"셀 수 없이 많다","mis":"M5-2-u1-X05"}],"explanation":["10 이상은 10과 같거나 크고, 10 이하는 10과 같거나 작아요.","크면서 작을 수는 없으니 같을 때만 둘 다 맞아요.","그래서 10 하나뿐이에요."]}'::jsonb),
('g5_2_math_u1_L02_challenge#3','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'sa','auto','63 이하인 자연수 중에서 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C1","difficulty":3,"kind":"sa","stem":"63 이하인 자연수 중에서 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["54","54개"],"explanation":["두 자리 수는 10부터예요. 63 이하이니 63까지 들어가요.","10부터 63까지 세면 63 − 10 + 1 = 54개예요.","63 − 10 = 53만 하면 하나를 빠뜨려요."],"variant_rule":{"alt":[{"stem":"45 이상인 자연수 중에서 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["55","55개"],"explanation":["45 이상이니 45부터, 두 자리 수는 99까지예요.","45부터 99까지 세면 99 − 45 + 1 = 55개예요.","끝수끼리 빼기만 하면 54로 하나를 빠뜨려요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#4','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'error','auto','「20 이상인 수」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X17']::text[],true,'{"seq":4,"concept":"M5-2-u1-C1","difficulty":3,"kind":"error","stem":"「20 이상인 수」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「20 이상인 자연수 중에서 가장 작은 수는 21이야.」","correct":true,"mis_target":"M5-2-u1-X01"},{"t":"서아 — 「20.5도 20 이상인 수야.」","mis":"M5-2-u1-X17"},{"t":"민준 — 「20 이상인 수는 셀 수 없이 많아.」","mis":"M5-2-u1-X17"}],"explanation":["20 이상인 수에는 20 자신이 들어가요.","그래서 가장 작은 자연수는 20이에요.","20.5도 들어가고, 20 이상인 수는 끝없이 많아요."],"variant_rule":{"alt":[{"stem":"「35 이하인 수」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「35 이하인 자연수 중에서 가장 큰 수는 34야.」","correct":true,"mis_target":"M5-2-u1-X01"},{"t":"태오 — 「34.9도 35 이하인 수야.」","mis":"M5-2-u1-X17"},{"t":"유나 — 「35 이하인 수는 수직선에 ●으로 그려.」","mis":"M5-2-u1-X17"}],"explanation":["35 이하인 수에는 35 자신이 들어가요.","그래서 가장 큰 자연수는 35예요.","34.9도 들어가고, ●으로 그려요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#5','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'sa','auto','키가 130 cm 이상이어야 탈 수 있는 놀이 기구가 있어요. 친구들의 키가 129.8 cm, 130 cm, 131.5 cm, 128 cm, 142 cm라면 탈 수 있는 친구는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C1","difficulty":3,"kind":"sa","stem":"키가 130 cm 이상이어야 탈 수 있는 놀이 기구가 있어요. 친구들의 키가 129.8 cm, 130 cm, 131.5 cm, 128 cm, 142 cm라면 탈 수 있는 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["3","3명"],"explanation":["130 cm 이상은 130 cm와 같거나 큰 키예요.","130 cm, 131.5 cm, 142 cm가 들어가요.","129.8 cm는 130보다 작아 빠져요 — 3명이에요."],"variant_rule":{"alt":[{"stem":"몸무게가 40 kg 이하인 사람만 탈 수 있는 그네가 있어요. 38 kg, 40 kg, 40.2 kg, 35.5 kg, 41 kg인 친구 중에서 탈 수 있는 친구는 몇 명인가요? 숫자로 쓰세요.","answer":["3","3명"],"explanation":["40 kg 이하는 40 kg과 같거나 가벼운 무게예요.","38 kg, 40 kg, 35.5 kg이 들어가요.","40.2 kg·41 kg은 빠지니 3명이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#6','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'mc','auto','「9세 (  ) 어린이는 입장료가 무료예요.」 딱 9세인 어린이도 무료라면 (  )에 알맞은 말은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],true,'{"seq":6,"concept":"M5-2-u1-C1","difficulty":3,"kind":"mc","stem":"「9세 (  ) 어린이는 입장료가 무료예요.」 딱 9세인 어린이도 무료라면 (  )에 알맞은 말은 어느 것인가요?","options":[{"t":"이하","correct":true},{"t":"미만","mis":"M5-2-u1-X02"},{"t":"이상","mis":"M5-2-u1-X03"},{"t":"초과","mis":"M5-2-u1-X03"}],"explanation":["어린이는 나이가 적은 쪽이니 「이하」나 「미만」이에요.","딱 9세도 무료라면 9세가 들어가야 해요.","경곗값을 넣는 말은 「이하」예요."],"variant_rule":{"alt":[{"stem":"「65세 (  ) 어르신은 지하철을 무료로 타요.」 딱 65세인 어르신도 무료라면 (  )에 알맞은 말은 어느 것인가요?","options":[{"t":"이상","correct":true},{"t":"초과","mis":"M5-2-u1-X02"},{"t":"이하","mis":"M5-2-u1-X03"},{"t":"미만","mis":"M5-2-u1-X03"}],"explanation":["어르신은 나이가 많은 쪽이니 「이상」이나 「초과」예요.","딱 65세도 무료라면 65세가 들어가야 해요.","경곗값을 넣는 말은 「이상」이에요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#7','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'sa','auto','7.5, 8, 6.9, 7.51, 3, 7.49, 10 중에서 7.5 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C1","difficulty":3,"kind":"sa","stem":"7.5, 8, 6.9, 7.51, 3, 7.49, 10 중에서 7.5 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["7.5 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 7.5, 6.9, 3, 7.49예요.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"2.39, 2.4, 2.41, 3, 1.9, 2.04 중에서 2.4 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["2.4 이상인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 2.4, 2.41, 3이에요.","모두 3개예요."]},{"stem":"0.8, 0.79, 0.81, 0.08, 1, 0.5 중에서 0.8 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["0.8 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 0.8, 0.79, 0.08, 0.5예요.","모두 4개예요."]}]}}'::jsonb),
('g5_2_math_u1_L02_challenge#8','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',4,'essay','teacher','영화관 안내판에 「12세 이상 관람 가」와 「12세 미만은 보호자 동반」이 함께 적혀 있어요. 딱 12세인 친구는 어느 줄에 들어가는지 쓰고, 두 줄이 함께 적혀 있는 까닭을 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C1","difficulty":4,"kind":"essay","stem":"영화관 안내판에 「12세 이상 관람 가」와 「12세 미만은 보호자 동반」이 함께 적혀 있어요. 딱 12세인 친구는 어느 줄에 들어가는지 쓰고, 두 줄이 함께 적혀 있는 까닭을 설명하세요.","answer_guide":{"answer":"예: 딱 12세는 「12세 이상」에 들어가 보호자 없이 볼 수 있다. 12세를 한쪽(이상)에만 넣고 다른 쪽(미만)에서는 빼서, 모든 나이가 두 무리 중 딱 한 곳에만 들어가도록 남김없이 나눈 것이다.","scoring_points":["12세가 「이상」 쪽에 들어감을 썼는가","「미만」에는 12세가 들어가지 않음을 밝혔는가","경곗값을 한쪽에만 넣어 겹치지 않게 나눴다는 까닭을 썼는가"]},"explanation":["12세 이상에는 12세가 들어가요.","12세 미만에는 12세가 들어가지 않아요.","경곗값을 한쪽에만 넣어 어느 나이든 한 곳에만 들어가요."]}'::jsonb),
('g5_2_math_u1_L02_challenge#9','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',4,'essay','teacher','「2 이상인 수」를 수직선에 나타내는 방법을 쓰고, 2에 속이 찬 ●을 그리는 까닭을 이상의 뜻으로 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C1","difficulty":4,"kind":"essay","stem":"「2 이상인 수」를 수직선에 나타내는 방법을 쓰고, 2에 속이 찬 ●을 그리는 까닭을 이상의 뜻으로 설명하세요.","answer_guide":{"answer":"예: 2에 ●을 그리고 오른쪽으로 선을 긋는다. 이상은 「같거나 크다」는 뜻이라 2 자신도 들어가므로 포함을 나타내는 ●으로 그린다.","scoring_points":["2에 ●을 그림을 썼는가","오른쪽으로 선을 그음을 썼는가","「같거나 크다」라서 2가 들어간다는 까닭을 썼는가"]},"explanation":["2 이상인 수는 2와 같거나 큰 수예요.","2가 들어가니 ●, 큰 쪽이니 오른쪽이에요.","이하였다면 왼쪽으로 그어요."]}'::jsonb),
('g5_2_math_u1_L02_challenge#10','math',5,2,'u1','L02','g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',4,'mc','auto','어떤 자연수 이상인 자연수 중에서 가장 작은 수 세 개를 더했더니 48이 되었어요. 어떤 자연수는 얼마인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16','M5-2-u1-X17']::text[],true,'{"seq":10,"concept":"M5-2-u1-C1","difficulty":4,"kind":"mc","stem":"어떤 자연수 이상인 자연수 중에서 가장 작은 수 세 개를 더했더니 48이 되었어요. 어떤 자연수는 얼마인가요?","options":[{"t":"15","correct":true},{"t":"14","mis":"M5-2-u1-X01"},{"t":"16","mis":"M5-2-u1-X16"},{"t":"17","mis":"M5-2-u1-X17"}],"explanation":["□ 이상이니 □ 자신부터 들어가요 — □, □ + 1, □ + 2를 더해 48이에요.","세 수의 가운데 수는 48 ÷ 3 = 16이라 세 수는 15, 16, 17이에요.","그래서 □ = 15예요. 확인: 15 + 16 + 17 = 48."],"variant_rule":{"alt":[{"stem":"어떤 자연수 이하인 자연수 중에서 가장 큰 수 세 개를 더했더니 57이 되었어요. 어떤 자연수는 얼마인가요?","options":[{"t":"20","correct":true},{"t":"21","mis":"M5-2-u1-X01"},{"t":"19","mis":"M5-2-u1-X16"},{"t":"18","mis":"M5-2-u1-X17"}],"explanation":["□ 이하이니 □ 자신부터 들어가요 — □, □ − 1, □ − 2를 더해 57이에요.","가운데 수는 57 ÷ 3 = 19라 세 수는 18, 19, 20이에요.","그래서 □ = 20이에요. 확인: 18 + 19 + 20 = 57."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#1','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'mc','auto','10 초과인 수를 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],true,'{"seq":1,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"10 초과인 수를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"10보다 큰 수","correct":true},{"t":"10과 같거나 큰 수","mis":"M5-2-u1-X02"},{"t":"10보다 작은 수","mis":"M5-2-u1-X03"},{"t":"10과 같거나 작은 수","mis":"M5-2-u1-X03"}],"explanation":["초과는 「그 수보다 큰 수」라는 뜻이에요.","10 초과인 수에는 10이 들어가지 않아요.","수직선에는 10에 ○으로 나타내요."],"variant_rule":{"alt":[{"stem":"8 미만인 수를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"8보다 작은 수","correct":true},{"t":"8과 같거나 작은 수","mis":"M5-2-u1-X02"},{"t":"8보다 큰 수","mis":"M5-2-u1-X03"},{"t":"8과 같거나 큰 수","mis":"M5-2-u1-X03"}],"explanation":["미만은 「그 수보다 작은 수」라는 뜻이에요.","8 미만인 수에는 8이 들어가지 않아요.","수직선에는 8에 ○으로 나타내요."]},{"stem":"25 초과인 수를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"25보다 큰 수","correct":true},{"t":"25와 같거나 큰 수","mis":"M5-2-u1-X02"},{"t":"25보다 작은 수","mis":"M5-2-u1-X03"},{"t":"25와 같거나 작은 수","mis":"M5-2-u1-X03"}],"explanation":["초과는 「그 수보다 큰 수」라는 뜻이에요.","25 초과인 수에는 25가 들어가지 않아요.","수직선에는 25에 ○으로 나타내요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#2','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'mc','auto','가방 10.5 kg, 13 kg, 10 kg, 12 kg 중에서 10 kg 초과가 아닌 것은 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],true,'{"seq":2,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"가방 10.5 kg, 13 kg, 10 kg, 12 kg 중에서 10 kg 초과가 아닌 것은 어느 것인가요?","options":[{"t":"10 kg","correct":true},{"t":"10.5 kg","mis":"M5-2-u1-X17"},{"t":"13 kg","mis":"M5-2-u1-X17"},{"t":"12 kg","mis":"M5-2-u1-X17"}],"explanation":["10 kg 초과는 경곗값을 포함하지 않아요.","10 kg만 범위에서 벗어나요.","그래서 아닌 것은 10 kg이에요."],"variant_rule":{"alt":[{"stem":"반려동물 6.4 kg, 7.9 kg, 8 kg, 5.5 kg 중에서 8 kg 미만이 아닌 것은 어느 것인가요?","options":[{"t":"8 kg","correct":true},{"t":"6.4 kg","mis":"M5-2-u1-X17"},{"t":"7.9 kg","mis":"M5-2-u1-X17"},{"t":"5.5 kg","mis":"M5-2-u1-X17"}],"explanation":["8 kg 미만은 경곗값을 포함하지 않아요.","8 kg만 범위에서 벗어나요.","그래서 아닌 것은 8 kg이에요."]},{"stem":"자동차 높이 4.5 m, 4.4 m, 5 m, 4.6 m 중에서 4.4 m 초과가 아닌 것은 어느 것인가요?","options":[{"t":"4.4 m","correct":true},{"t":"4.5 m","mis":"M5-2-u1-X17"},{"t":"5 m","mis":"M5-2-u1-X17"},{"t":"4.6 m","mis":"M5-2-u1-X17"}],"explanation":["4.4 m 초과는 경곗값을 포함하지 않아요.","4.4 m만 범위에서 벗어나요.","그래서 아닌 것은 4.4 m예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#3','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'sa','auto','40, 39.9, 41, 52, 40.1, 38 중에서 40 초과인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":1,"kind":"sa","stem":"40, 39.9, 41, 52, 40.1, 38 중에서 40 초과인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["40 초과인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 41, 52, 40.1이에요.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"31.9, 32, 30, 32.1, 25, 31 중에서 32 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["32 미만인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 31.9, 30, 25, 31이에요.","모두 4개예요."]},{"stem":"15, 15.2, 14.9, 20, 16 중에서 15 초과인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["15 초과인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 15.2, 20, 16이에요.","모두 3개예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#4','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'mc','auto','수직선에 34에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],true,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"수직선에 34에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"34 초과인 수","correct":true},{"t":"34 이상인 수","mis":"M5-2-u1-X04"},{"t":"34 미만인 수","mis":"M5-2-u1-X03"},{"t":"34 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","34는 ○이라 포함하지 않아요.","그래서 34 초과인 수예요."],"variant_rule":{"alt":[{"stem":"수직선에 8에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"8 미만인 수","correct":true},{"t":"8 이하인 수","mis":"M5-2-u1-X04"},{"t":"8 초과인 수","mis":"M5-2-u1-X03"},{"t":"8 이상인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","8은 ○이라 포함하지 않아요.","그래서 8 미만인 수예요."]},{"stem":"수직선에 19에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"19 초과인 수","correct":true},{"t":"19 이상인 수","mis":"M5-2-u1-X04"},{"t":"19 미만인 수","mis":"M5-2-u1-X03"},{"t":"19 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","19는 ○이라 포함하지 않아요.","그래서 19 초과인 수예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#5','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'mc','auto','「8 kg 미만인 반려동물만 비행기에 데리고 탈 수 있어요.」 무게가 딱 8 kg인 반려동물은 어떻게 될까요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X17']::text[],true,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":2,"kind":"mc","stem":"「8 kg 미만인 반려동물만 비행기에 데리고 탈 수 있어요.」 무게가 딱 8 kg인 반려동물은 어떻게 될까요?","options":[{"t":"데리고 탈 수 없다","correct":true},{"t":"데리고 탈 수 있다","mis":"M5-2-u1-X02"},{"t":"9 kg까지는 데리고 탈 수 있다","mis":"M5-2-u1-X03"},{"t":"보호자가 안아 주면 탈 수 있다","mis":"M5-2-u1-X17"}],"explanation":["8 kg 미만은 8 kg보다 가벼운 무게예요.","경곗값 8 kg은 들어가지 않아요.","그래서 딱 8 kg인 반려동물은 데리고 탈 수 없어요."],"variant_rule":{"alt":[{"stem":"「높이가 4.4 m를 초과하는 자동차는 해저 터널을 지나갈 수 없어요.」 높이가 딱 4.4 m인 자동차는 어떻게 될까요?","options":[{"t":"지나갈 수 있다","correct":true},{"t":"지나갈 수 없다","mis":"M5-2-u1-X02"},{"t":"4.3 m까지만 지나갈 수 있다","mis":"M5-2-u1-X02"},{"t":"4.5 m인 자동차도 지나갈 수 있다","mis":"M5-2-u1-X03"}],"explanation":["4.4 m 초과는 4.4 m보다 높은 것이에요.","경곗값 4.4 m는 초과에 들어가지 않아요.","그래서 딱 4.4 m인 자동차는 지나갈 수 있어요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#6','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'mc','auto','높이가 4.4 m를 초과하는 자동차는 해저 터널을 지나갈 수 없어요. 가 3.9 m, 나 4.5 m, 다 4.4 m, 라 4.8 m 중에서 지나갈 수 없는 자동차를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":6,"concept":"M5-2-u1-C2","difficulty":2,"kind":"mc","stem":"높이가 4.4 m를 초과하는 자동차는 해저 터널을 지나갈 수 없어요. 가 3.9 m, 나 4.5 m, 다 4.4 m, 라 4.8 m 중에서 지나갈 수 없는 자동차를 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나, 다, 라","mis":"M5-2-u1-X02"},{"t":"가, 다","mis":"M5-2-u1-X03"},{"t":"라","mis":"M5-2-u1-X16"}],"explanation":["4.4 m 초과는 4.4 m보다 높은 것이에요.","4.5 m와 4.8 m가 4.4 m보다 높아요. 다(4.4 m)는 딱 4.4 m라 빠져요.","지나갈 수 없는 자동차는 나, 라예요."],"variant_rule":{"alt":[{"stem":"무게가 10 kg을 초과하는 가방은 비행기에 들고 탈 수 없어요. 가 9.5 kg, 나 10 kg, 다 10.5 kg, 라 13 kg 중에서 들고 탈 수 없는 가방을 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"나, 다, 라","mis":"M5-2-u1-X02"},{"t":"가, 나","mis":"M5-2-u1-X03"},{"t":"라","mis":"M5-2-u1-X16"}],"explanation":["10 kg 초과는 10 kg보다 무거운 것이에요.","10.5 kg과 13 kg이 들어가요. 나(10 kg)는 딱 10 kg이라 빠져요.","들고 탈 수 없는 가방은 다, 라예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#7','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'error','auto','두 친구가 말했어요. 잘못 말한 친구는 누구인가요? 선재 — 「64세 미만에는 64세도 포함돼요.」 연서 — 「11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요.」',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],true,'{"seq":7,"concept":"M5-2-u1-C2","difficulty":2,"kind":"error","stem":"두 친구가 말했어요. 잘못 말한 친구는 누구인가요? 선재 — 「64세 미만에는 64세도 포함돼요.」 연서 — 「11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요.」","options":[{"t":"선재","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"연서","mis":"M5-2-u1-X17"},{"t":"둘 다 맞다","mis":"M5-2-u1-X02"}],"explanation":["미만은 경곗값을 포함하지 않아요 — 64세 미만에 64세는 빠져요.","12세 초과는 12세보다 많은 나이라 13세만 들어가요.","그래서 잘못 말한 친구는 선재예요."],"variant_rule":{"alt":[{"stem":"두 친구가 말했어요. 잘못 말한 친구는 누구인가요? 하윤 — 「30 초과인 자연수 중에서 가장 작은 수는 31이에요.」 도현 — 「5 미만인 자연수는 1, 2, 3, 4, 5예요.」","options":[{"t":"도현","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"하윤","mis":"M5-2-u1-X17"},{"t":"둘 다 맞다","mis":"M5-2-u1-X02"}],"explanation":["30 초과는 30보다 큰 수라 가장 작은 자연수는 31이에요.","5 미만에는 5가 들어가지 않아 1, 2, 3, 4뿐이에요.","그래서 잘못 말한 친구는 도현이에요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#8','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'sa','auto','11세, 12세, 13세 중에서 12세 초과인 나이는 몇 세인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"11세, 12세, 13세 중에서 12세 초과인 나이는 몇 세인가요? 숫자로 쓰세요.","answer":["13","13세"],"explanation":["12세 초과는 12세보다 많은 나이예요.","12세는 딱 12세라 빠지고, 11세는 적어서 빠져요.","13세뿐이에요."],"variant_rule":{"alt":[{"stem":"7세, 8세, 9세 중에서 8세 미만인 나이는 몇 세인가요? 숫자로 쓰세요.","answer":["7","7세"],"explanation":["8세 미만은 8세보다 적은 나이예요.","8세는 빠지고 9세는 많아서 빠져요.","7세뿐이에요."]},{"stem":"20, 21, 22 중에서 21 초과인 수는 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["21 초과는 21보다 큰 수예요.","21은 빠지고 20은 작아서 빠져요.","22뿐이에요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#9','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'ox','auto','10 이상인 수와 10 초과인 수는 10을 넣는지 넣지 않는지 하나만 달라요.',ARRAY['M5-2-u1-X02']::text[],true,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":2,"kind":"ox","stem":"10 이상인 수와 10 초과인 수는 10을 넣는지 넣지 않는지 하나만 달라요.","answer":"O","reason_options":[{"t":"10 이상은 10을 포함하고 10 초과는 포함하지 않아서","correct":true},{"t":"두 말은 완전히 같은 뜻이어서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["10 이상은 10과 같거나 큰 수예요.","10 초과는 10보다 큰 수예요.","경곗값 10 하나만 달라요 — ●과 ○의 차이예요."],"variant_rule":{"alt":[{"stem":"8 미만인 수와 8 이하인 수는 똑같아요.","answer":"X","reason_options":[{"t":"8 이하에는 8이 들어가고 8 미만에는 8이 들어가지 않아서","correct":true},{"t":"미만과 이하는 같은 말이어서","mis":"M5-2-u1-X02"}],"explanation":["8 미만은 8보다 작은 수예요.","8 이하는 8과 같거나 작은 수예요.","8이 들어가는지가 달라요."]}]}}'::jsonb),
('g5_2_math_u1_L03_basic#10','math',5,2,'u1','L03','g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',3,'mc','auto','8 미만인 수에 들어가는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X03','M5-2-u1-X02']::text[],true,'{"seq":10,"concept":"M5-2-u1-C2","difficulty":3,"kind":"mc","stem":"8 미만인 수에 들어가는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 6, 7","correct":true},{"t":"8, 9, 10","mis":"M5-2-u1-X03"},{"t":"6, 8, 9","mis":"M5-2-u1-X03"},{"t":"7, 8","mis":"M5-2-u1-X02"}],"explanation":["8 미만은 8보다 작은 수예요.","8은 들어가지 않고, 9·10은 커서 빠져요.","모두 들어가는 것은 5, 6, 7이에요."],"variant_rule":{"alt":[{"stem":"20 초과인 수에 들어가는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"21, 22, 23","correct":true},{"t":"18, 19, 20","mis":"M5-2-u1-X03"},{"t":"19, 21, 22","mis":"M5-2-u1-X03"},{"t":"20, 21","mis":"M5-2-u1-X02"}],"explanation":["20 초과는 20보다 큰 수예요.","20은 들어가지 않고, 18·19는 작아서 빠져요.","모두 들어가는 것은 21, 22, 23이에요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#1','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',2,'sa','auto','31.9, 32, 30, 32.1, 25, 31 중에서 32 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"31.9, 32, 30, 32.1, 25, 31 중에서 32 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["32 미만인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 31.9, 30, 25, 31이에요.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"7.5, 7.51, 8, 7.49, 9, 6 중에서 7.5 초과인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["7.5 초과인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 7.51, 8, 9예요.","모두 3개예요."]},{"stem":"1.19, 1.2, 0.9, 1.21, 1 중에서 1.2 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["1.2 미만인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 1.19, 0.9, 1이에요.","모두 3개예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#2','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',2,'match','auto','수의 범위와 그 뜻을 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u1-C2","difficulty":2,"kind":"match","stem":"수의 범위와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"10 이상인 수","r":"10과 같거나 큰 수"},{"l":"10 초과인 수","r":"10보다 큰 수"},{"l":"10 미만인 수","r":"10보다 작은 수"}],"mis":"M5-2-u1-X02","explanation":["이상·이하는 「같거나」가 붙어요.","초과·미만은 그 수를 넣지 않아요.","10 초과는 「10보다 큰 수」, 10 미만은 「10보다 작은 수」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 수의 범위와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"6 이하인 수","r":"6과 같거나 작은 수"},{"l":"6 미만인 수","r":"6보다 작은 수"},{"l":"6 초과인 수","r":"6보다 큰 수"}],"explanation":["이상·이하는 「같거나」가 붙어요.","6 미만은 6을 넣지 않은 작은 쪽이에요.","6 초과는 6을 넣지 않은 큰 쪽이에요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#3','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'sa','auto','50 미만인 자연수 중에서 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":3,"kind":"sa","stem":"50 미만인 자연수 중에서 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["40","40개"],"explanation":["두 자리 수는 10부터예요. 50 미만이니 50은 빠지고 49까지예요.","10부터 49까지 세면 49 − 10 + 1 = 40개예요.","50까지 넣으면 41개로 하나 많아져요."],"variant_rule":{"alt":[{"stem":"75 초과인 자연수 중에서 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24","24개"],"explanation":["75 초과이니 75는 빠지고 76부터, 두 자리 수는 99까지예요.","76부터 99까지 세면 99 − 76 + 1 = 24개예요.","75를 넣으면 25개로 하나 많아져요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#4','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'mc','auto','다음 중 20을 포함하지 않는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16']::text[],true,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":3,"kind":"mc","stem":"다음 중 20을 포함하지 않는 수의 범위는 어느 것인가요?","options":[{"t":"20 미만인 수","correct":true},{"t":"20 이상인 수","mis":"M5-2-u1-X01"},{"t":"20 이하인 수","mis":"M5-2-u1-X01"},{"t":"19.5 초과인 수","mis":"M5-2-u1-X16"}],"explanation":["이상·이하는 경곗값 20을 포함해요.","19.5 초과는 19.5보다 큰 수라 20이 들어가요.","20 미만에만 20이 들어가지 않아요."],"variant_rule":{"alt":[{"stem":"다음 중 15를 포함하는 수의 범위는 어느 것인가요?","options":[{"t":"15 이하인 수","correct":true},{"t":"15 초과인 수","mis":"M5-2-u1-X02"},{"t":"15 미만인 수","mis":"M5-2-u1-X02"},{"t":"15.5 이상인 수","mis":"M5-2-u1-X16"}],"explanation":["초과·미만은 경곗값 15를 포함하지 않아요.","15.5 이상은 15.5와 같거나 큰 수라 15가 빠져요.","15 이하에만 15가 들어가요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#5','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'mc','auto','어떤 수 미만인 자연수가 모두 7개예요. 어떤 수가 자연수라면 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X06','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":3,"kind":"mc","stem":"어떤 수 미만인 자연수가 모두 7개예요. 어떤 수가 자연수라면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"7","mis":"M5-2-u1-X02"},{"t":"9","mis":"M5-2-u1-X06"},{"t":"6","mis":"M5-2-u1-X16"}],"explanation":["1부터 세어 7개면 1, 2, 3, 4, 5, 6, 7이에요.","미만은 경곗값이 빠지니 7 다음 수 8이 어떤 수예요.","확인: 8 미만인 자연수는 1~7로 7개예요."],"variant_rule":{"alt":[{"stem":"어떤 수 이하인 자연수가 모두 9개예요. 어떤 수가 자연수라면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"10","mis":"M5-2-u1-X01"},{"t":"8","mis":"M5-2-u1-X06"},{"t":"11","mis":"M5-2-u1-X16"}],"explanation":["1부터 세어 9개면 1~9예요.","이하는 경곗값이 들어가니 마지막 수 9가 어떤 수예요.","확인: 9 이하인 자연수는 1~9로 9개예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#6','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'error','auto','공항 안내판에 「10 kg 초과 가방은 짐칸으로 보내요」라고 적혀 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],true,'{"seq":6,"concept":"M5-2-u1-C2","difficulty":3,"kind":"error","stem":"공항 안내판에 「10 kg 초과 가방은 짐칸으로 보내요」라고 적혀 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「딱 10 kg인 가방도 짐칸으로 보내야 해.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"지후 — 「10.1 kg인 가방은 짐칸으로 보내.」","mis":"M5-2-u1-X17"},{"t":"채윤 — 「9.9 kg인 가방은 들고 탈 수 있어.」","mis":"M5-2-u1-X17"}],"explanation":["10 kg 초과는 10 kg보다 무거운 것이에요.","딱 10 kg은 초과에 들어가지 않아 들고 탈 수 있어요.","그래서 잘못 말한 친구는 수아예요."],"variant_rule":{"alt":[{"stem":"엘리베이터에 「13세 미만 어린이는 보호자와 함께」라고 적혀 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「딱 13세인 나도 보호자와 함께 타야 해.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"다인 — 「12세인 동생은 보호자와 함께 타.」","mis":"M5-2-u1-X17"},{"t":"시윤 — 「14세인 형은 혼자 타도 돼.」","mis":"M5-2-u1-X17"}],"explanation":["13세 미만은 13세보다 적은 나이예요.","딱 13세는 미만에 들어가지 않아 혼자 탈 수 있어요.","그래서 잘못 말한 친구는 은호예요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#7','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'mc','auto','12 kg을 초과하는 가방에만 추가 요금을 받아요. 11.9 kg, 12 kg, 12.1 kg인 가방 중에서 추가 요금을 내는 가방은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X05']::text[],true,'{"seq":7,"concept":"M5-2-u1-C2","difficulty":3,"kind":"mc","stem":"12 kg을 초과하는 가방에만 추가 요금을 받아요. 11.9 kg, 12 kg, 12.1 kg인 가방 중에서 추가 요금을 내는 가방은 어느 것인가요?","options":[{"t":"12.1 kg 하나","correct":true},{"t":"12 kg, 12.1 kg","mis":"M5-2-u1-X02"},{"t":"11.9 kg 하나","mis":"M5-2-u1-X03"},{"t":"세 가방 모두","mis":"M5-2-u1-X05"}],"explanation":["12 kg 초과는 12 kg보다 무거운 것이에요.","12 kg은 딱 경곗값이라 빠지고 11.9 kg은 가벼워서 빠져요.","12.1 kg 하나만 추가 요금을 내요."],"variant_rule":{"alt":[{"stem":"5 kg 미만인 소포만 작은 상자에 담아요. 4.9 kg, 5 kg, 5.1 kg인 소포 중에서 작은 상자에 담는 것은 어느 것인가요?","options":[{"t":"4.9 kg 하나","correct":true},{"t":"4.9 kg, 5 kg","mis":"M5-2-u1-X02"},{"t":"5.1 kg 하나","mis":"M5-2-u1-X03"},{"t":"세 소포 모두","mis":"M5-2-u1-X05"}],"explanation":["5 kg 미만은 5 kg보다 가벼운 것이에요.","5 kg은 빠지고 5.1 kg은 무거워서 빠져요.","4.9 kg 하나만 담아요."]}]}}'::jsonb),
('g5_2_math_u1_L03_challenge#8','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',4,'essay','teacher','「10 kg 초과 가방은 들고 탈 수 없어요.」 무게가 딱 10 kg인 가방은 들고 탈 수 있는지 판단하고, 초과의 뜻을 들어 까닭을 쓰세요. 「10 kg 이상」이었다면 어떻게 달라지는지도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「10 kg 초과 가방은 들고 탈 수 없어요.」 무게가 딱 10 kg인 가방은 들고 탈 수 있는지 판단하고, 초과의 뜻을 들어 까닭을 쓰세요. 「10 kg 이상」이었다면 어떻게 달라지는지도 쓰세요.","answer_guide":{"answer":"예: 들고 탈 수 있다. 10 kg 초과는 10 kg보다 무거운 것만 뜻해 딱 10 kg은 들어가지 않기 때문이다. 「10 kg 이상」이었다면 10 kg도 들어가 들고 탈 수 없다.","scoring_points":["들고 탈 수 있다고 판단했는가","초과는 경곗값을 넣지 않는다는 까닭을 썼는가","「이상」이면 10 kg도 들어가 달라짐을 썼는가"]},"explanation":["초과는 그 수보다 큰 것만 뜻해요.","딱 10 kg은 들어가지 않으니 들고 탈 수 있어요.","「이상」이면 10 kg도 들어가 결과가 바뀌어요."]}'::jsonb),
('g5_2_math_u1_L03_challenge#9','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',4,'essay','teacher','「8 이하인 수」와 「8 미만인 수」를 수직선에 각각 어떻게 나타내는지 쓰고, 두 그림이 어디가 다른지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「8 이하인 수」와 「8 미만인 수」를 수직선에 각각 어떻게 나타내는지 쓰고, 두 그림이 어디가 다른지 설명하세요.","answer_guide":{"answer":"예: 8 이하는 8에 ●을 그리고 왼쪽으로 선을 긋는다. 8 미만은 8에 ○을 그리고 왼쪽으로 선을 긋는다. 방향은 같고, 8을 포함하는지(●)·포함하지 않는지(○)만 다르다.","scoring_points":["8 이하를 ●과 왼쪽으로 나타냈는가","8 미만을 ○과 왼쪽으로 나타냈는가","경곗값 포함 여부(●·○)만 다르다고 설명했는가"]},"explanation":["8 이하 — 8에 ●, 왼쪽으로 선이에요.","8 미만 — 8에 ○, 왼쪽으로 선이에요.","8을 포함하는지만 달라요."]}'::jsonb),
('g5_2_math_u1_L03_challenge#10','math',5,2,'u1','L03','g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',4,'mc','auto','어떤 자연수 초과인 자연수 중에서 가장 작은 수 세 개를 더했더니 48이 되었어요. 어떤 자연수는 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":10,"concept":"M5-2-u1-C2","difficulty":4,"kind":"mc","stem":"어떤 자연수 초과인 자연수 중에서 가장 작은 수 세 개를 더했더니 48이 되었어요. 어떤 자연수는 얼마인가요?","options":[{"t":"14","correct":true},{"t":"15","mis":"M5-2-u1-X02"},{"t":"16","mis":"M5-2-u1-X16"},{"t":"13","mis":"M5-2-u1-X16"}],"explanation":["□ 초과이니 □는 빠지고 □ + 1부터 세 수예요.","세 수의 가운데 수는 48 ÷ 3 = 16이라 세 수는 15, 16, 17이에요.","15가 □ + 1이니 □ = 14예요."],"variant_rule":{"alt":[{"stem":"어떤 자연수 미만인 자연수 중에서 가장 큰 수 세 개를 더했더니 57이 되었어요. 어떤 자연수는 얼마인가요?","options":[{"t":"21","correct":true},{"t":"20","mis":"M5-2-u1-X02"},{"t":"19","mis":"M5-2-u1-X16"},{"t":"22","mis":"M5-2-u1-X16"}],"explanation":["□ 미만이니 □는 빠지고 □ − 1부터 세 수예요.","가운데 수는 57 ÷ 3 = 19라 세 수는 18, 19, 20이에요.","20이 □ − 1이니 □ = 21이에요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#1','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 경고 단계의 체감 온도 범위는 어느 것인가요?',ARRAY['M5-2-u1-X05','M5-2-u1-X04']::text[],true,'{"seq":1,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 경고 단계의 체감 온도 범위는 어느 것인가요?","options":[{"t":"34 °C 이상 37 °C 미만","correct":true},{"t":"31 °C 이상 34 °C 미만","mis":"M5-2-u1-X05"},{"t":"37 °C 이상","mis":"M5-2-u1-X05"},{"t":"34 °C 초과 37 °C 이하","mis":"M5-2-u1-X04"}],"explanation":["표에서 경고 줄을 찾아 읽어요.","경고는 34 °C 이상 37 °C 미만이에요.","34 °C는 들어가고 37 °C는 위험 단계로 넘어가요."],"variant_rule":{"alt":[{"stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 주의 단계의 체감 온도 범위는 어느 것인가요?","options":[{"t":"31 °C 이상 34 °C 미만","correct":true},{"t":"29 °C 이상 31 °C 미만","mis":"M5-2-u1-X05"},{"t":"34 °C 이상 37 °C 미만","mis":"M5-2-u1-X05"},{"t":"31 °C 초과 34 °C 이하","mis":"M5-2-u1-X04"}],"explanation":["표에서 주의 줄을 찾아 읽어요.","주의는 31 °C 이상 34 °C 미만이에요.","31 °C는 들어가고 34 °C는 경고로 넘어가요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#2','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 31 °C라면 어느 단계인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X05']::text[],true,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 31 °C라면 어느 단계인가요?","options":[{"t":"주의","correct":true},{"t":"관심","mis":"M5-2-u1-X02"},{"t":"경고","mis":"M5-2-u1-X05"},{"t":"위험","mis":"M5-2-u1-X05"}],"explanation":["주의 단계는 31 °C 이상 34 °C 미만이에요.","31 °C는 이 범위에 들어가요.","바로 아래 단계는 경곗값을 포함하지 않아 겹치지 않아요."],"variant_rule":{"alt":[{"stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 34 °C라면 어느 단계인가요?","options":[{"t":"경고","correct":true},{"t":"주의","mis":"M5-2-u1-X02"},{"t":"관심","mis":"M5-2-u1-X05"},{"t":"위험","mis":"M5-2-u1-X05"}],"explanation":["경고 단계는 34 °C 이상 37 °C 미만이에요.","34 °C는 이 범위에 들어가요.","바로 아래 단계는 경곗값을 포함하지 않아 겹치지 않아요."]},{"stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 37 °C라면 어느 단계인가요?","options":[{"t":"위험","correct":true},{"t":"경고","mis":"M5-2-u1-X02"},{"t":"관심","mis":"M5-2-u1-X05"},{"t":"주의","mis":"M5-2-u1-X05"}],"explanation":["위험 단계는 37 °C 이상이에요.","37 °C는 이 범위에 들어가요.","바로 아래 단계는 경곗값을 포함하지 않아 겹치지 않아요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#3','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'sa','auto','5 이상 10 이하인 수 중에서 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":1,"kind":"sa","stem":"5 이상 10 이하인 수 중에서 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6","6개"],"explanation":["5 이상 10 이하인 수에 드는 자연수는 5부터 10까지예요.","양 끝이 모두 들어가요.","세면 10 − 5 + 1 = 6개예요."],"variant_rule":{"alt":[{"stem":"5 이상 10 미만인 수 중에서 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["5 이상 10 미만인 수에 드는 자연수는 5부터 9까지예요.","○으로 나타내는 끝은 빠져요.","세면 9 − 5 + 1 = 5개예요."]},{"stem":"3 초과 9 이하인 수 중에서 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6","6개"],"explanation":["3 초과 9 이하인 수에 드는 자연수는 4부터 9까지예요.","○으로 나타내는 끝은 빠져요.","세면 9 − 4 + 1 = 6개예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#4','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','수직선에 5에는 ●, 10에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],true,'{"seq":4,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"수직선에 5에는 ●, 10에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"5 이상 10 미만인 수","correct":true},{"t":"5 초과 10 미만인 수","mis":"M5-2-u1-X04"},{"t":"5 이상 10 이하인 수","mis":"M5-2-u1-X04"},{"t":"5 초과 10 이하인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","5는 ●이라 포함해요 · 10은 ○이라 포함하지 않아요.","그래서 5 이상 10 미만인 수예요."],"variant_rule":{"alt":[{"stem":"수직선에 52에는 ●, 58에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"52 이상 58 이하인 수","correct":true},{"t":"52 초과 58 이하인 수","mis":"M5-2-u1-X04"},{"t":"52 이상 58 미만인 수","mis":"M5-2-u1-X04"},{"t":"52 초과 58 미만인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","52는 ●이라 포함해요 · 58은 ●이라 포함해요.","그래서 52 이상 58 이하인 수예요."]},{"stem":"수직선에 12에는 ○, 24에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"12 초과 24 미만인 수","correct":true},{"t":"12 이상 24 미만인 수","mis":"M5-2-u1-X04"},{"t":"12 초과 24 이하인 수","mis":"M5-2-u1-X04"},{"t":"12 이상 24 이하인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","12는 ○이라 포함하지 않아요 · 24는 ○이라 포함하지 않아요.","그래서 12 초과 24 미만인 수예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#5','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 20 kg인 소포의 요금은 얼마인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 20 kg인 소포의 요금은 얼마인가요?","options":[{"t":"7000원","correct":true},{"t":"9000원","mis":"M5-2-u1-X01"},{"t":"5000원","mis":"M5-2-u1-X16"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["20 kg은 「10 kg 초과 20 kg 이하」에 들어가요 — 이하라 20 kg이 포함돼요.","「20 kg 초과 25 kg 이하」에는 20 kg이 들어가지 않아요.","그래서 요금은 7000원이에요."],"variant_rule":{"alt":[{"stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 5 kg인 소포의 요금은 얼마인가요?","options":[{"t":"4000원","correct":true},{"t":"5000원","mis":"M5-2-u1-X01"},{"t":"7000원","mis":"M5-2-u1-X16"},{"t":"9000원","mis":"M5-2-u1-X16"}],"explanation":["5 kg은 「5 kg 이하」에 들어가요.","「5 kg 초과 10 kg 이하」에는 5 kg이 빠져요.","그래서 요금은 4000원이에요."]},{"stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 10.5 kg인 소포의 요금은 얼마인가요?","options":[{"t":"7000원","correct":true},{"t":"5000원","mis":"M5-2-u1-X03"},{"t":"9000원","mis":"M5-2-u1-X16"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["10.5 kg은 10 kg보다 무거워요.","「10 kg 초과 20 kg 이하」에 들어가요.","그래서 요금은 7000원이에요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#6','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 윤우는 8세예요. 한 번에 몇 mL를 먹어야 하나요?',ARRAY['M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 윤우는 8세예요. 한 번에 몇 mL를 먹어야 하나요?","options":[{"t":"7.5 mL","correct":true},{"t":"5 mL","mis":"M5-2-u1-X03"},{"t":"10 mL","mis":"M5-2-u1-X03"},{"t":"3.75 mL","mis":"M5-2-u1-X16"}],"explanation":["8세는 7세와 같거나 많고 11세보다 적어요.","「7세 이상 11세 미만」 줄에 들어가요.","한 번에 7.5 mL예요."],"variant_rule":{"alt":[{"stem":"어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 하은이는 7세예요. 한 번에 몇 mL를 먹어야 하나요?","options":[{"t":"7.5 mL","correct":true},{"t":"5 mL","mis":"M5-2-u1-X02"},{"t":"10 mL","mis":"M5-2-u1-X03"},{"t":"3.75 mL","mis":"M5-2-u1-X16"}],"explanation":["7세는 「7세 이상」에 들어가요.","「4세 이상 7세 미만」에는 7세가 빠져요.","한 번에 7.5 mL예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#7','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'sa','auto','어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 서진이는 11세예요. 한 번에 몇 mL를 먹어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 서진이는 11세예요. 한 번에 몇 mL를 먹어야 하나요? 숫자로 쓰세요.","answer":["10","10mL","10 mL"],"explanation":["11세는 「7세 이상 11세 미만」에는 빠져요 — 미만이에요.","「11세 이상 15세 미만」에 들어가요.","한 번에 10 mL예요."],"variant_rule":{"alt":[{"stem":"어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 동생은 5세예요. 한 번에 몇 mL를 먹어야 하나요? 숫자로 쓰세요.","answer":["5","5mL","5 mL"],"explanation":["5세는 4세와 같거나 많고 7세보다 적어요.","「4세 이상 7세 미만」에 들어가요.","한 번에 5 mL예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#8','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','5, 7, 9.9, 10 중에서 5 이상 10 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X05','M5-2-u1-X01','M5-2-u1-X02']::text[],true,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"5, 7, 9.9, 10 중에서 5 이상 10 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 7, 9.9","correct":true},{"t":"7, 9.9, 10","mis":"M5-2-u1-X05"},{"t":"7, 9.9","mis":"M5-2-u1-X01"},{"t":"5, 7, 9.9, 10","mis":"M5-2-u1-X02"}],"explanation":["5 이상이니 5가 들어가고, 10 미만이니 10은 빠져요.","7과 9.9는 그 사이에 있어요.","그래서 5, 7, 9.9예요."],"variant_rule":{"alt":[{"stem":"12, 15, 17.5, 18 중에서 12 초과 18 이하인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"15, 17.5, 18","correct":true},{"t":"12, 15, 17.5","mis":"M5-2-u1-X05"},{"t":"15, 17.5","mis":"M5-2-u1-X01"},{"t":"12, 15, 17.5, 18","mis":"M5-2-u1-X02"}],"explanation":["12 초과이니 12는 빠지고, 18 이하이니 18은 들어가요.","15와 17.5는 그 사이에 있어요.","그래서 15, 17.5, 18이에요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#9','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'ox','auto','어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 30.9 °C면 주의 단계예요.',ARRAY['M5-2-u1-X05']::text[],true,'{"seq":9,"concept":"M5-2-u1-C3","difficulty":2,"kind":"ox","stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 30.9 °C면 주의 단계예요.","answer":"X","reason_options":[{"t":"관심이 29 °C 이상 31 °C 미만이라 30.9 °C가 관심에 들어가서","correct":true},{"t":"30.9는 31에 아주 가까워서 주의로 쳐서","mis":"M5-2-u1-X05"}],"mis":"M5-2-u1-X05","explanation":["30.9는 29와 같거나 크고 31보다 작아요.","그래서 관심 단계예요.","주의는 31 °C부터라 30.9 °C는 아직 아니에요."],"variant_rule":{"alt":[{"stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 예상 체감 온도가 34 °C면 경고 단계예요.","answer":"O","reason_options":[{"t":"경고가 34 °C 이상 37 °C 미만이라 34 °C가 들어가서","correct":true},{"t":"주의 단계가 34 °C까지라서","mis":"M5-2-u1-X02"}],"explanation":["경고는 34 °C 이상이라 34가 들어가요.","주의는 34 °C 미만이라 34가 빠져요.","그래서 34 °C는 경고 단계예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_basic#10','math',5,2,'u1','L04','g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',3,'mc','auto','윗몸 말아 올리기 등급 — 1등급 60회 이상 · 2등급 40회 이상 60회 미만 · 3등급 20회 이상 40회 미만 · 4등급 20회 미만. 기록은 가희 37회, 성윤 40회, 나리 22회, 유나 39회, 지아 60회예요. 가희와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16','M5-2-u1-X03']::text[],true,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"윗몸 말아 올리기 등급 — 1등급 60회 이상 · 2등급 40회 이상 60회 미만 · 3등급 20회 이상 40회 미만 · 4등급 20회 미만. 기록은 가희 37회, 성윤 40회, 나리 22회, 유나 39회, 지아 60회예요. 가희와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"나리, 유나","correct":true},{"t":"성윤, 나리, 유나","mis":"M5-2-u1-X02"},{"t":"나리","mis":"M5-2-u1-X16"},{"t":"성윤, 지아","mis":"M5-2-u1-X03"}],"explanation":["가희 37회는 「20회 이상 40회 미만」 — 3등급이에요.","나리 22회·유나 39회도 같은 범위예요. 성윤 40회는 40회 미만에 빠져 2등급이에요.","그래서 나리, 유나예요."],"variant_rule":{"alt":[{"stem":"윗몸 말아 올리기 등급 — 1등급 60회 이상 · 2등급 40회 이상 60회 미만 · 3등급 20회 이상 40회 미만 · 4등급 20회 미만. 기록은 준서 45회, 다온 60회, 라희 59회, 민호 40회, 서아 38회예요. 준서와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"라희, 민호","correct":true},{"t":"다온, 라희, 민호","mis":"M5-2-u1-X02"},{"t":"라희","mis":"M5-2-u1-X01"},{"t":"다온, 서아","mis":"M5-2-u1-X03"}],"explanation":["준서 45회는 「40회 이상 60회 미만」 — 2등급이에요.","라희 59회·민호 40회도 같아요. 다온 60회는 1등급이에요.","그래서 라희, 민호예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#1','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',2,'sa','auto','24, 14.6, 24.5, 17, 12, 20.7, 22, 10.1 중에서 12 초과 24 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"24, 14.6, 24.5, 17, 12, 20.7, 22, 10.1 중에서 12 초과 24 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["12 초과 24 미만인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 14.6, 17, 20.7, 22예요.","모두 4개예요."],"variant_rule":{"alt":[{"stem":"2.9, 3, 4.5, 6, 6.1, 5 중에서 3 이상 6 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["3 이상 6 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 3, 4.5, 6, 5예요.","모두 4개예요."]},{"stem":"40, 41, 50, 50.5, 45.5, 39 중에서 40 초과 50 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["40 초과 50 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 41, 50, 45.5예요.","모두 3개예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#2','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',2,'mc','auto','내일 예상 강수량이 5 mm 이상 10 mm 이하래요. 다음 중 이 범위에 들어가지 않는 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X17']::text[],true,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"내일 예상 강수량이 5 mm 이상 10 mm 이하래요. 다음 중 이 범위에 들어가지 않는 것은 어느 것인가요?","options":[{"t":"10.5 mm","correct":true},{"t":"5 mm","mis":"M5-2-u1-X01"},{"t":"10 mm","mis":"M5-2-u1-X01"},{"t":"7.5 mm","mis":"M5-2-u1-X17"}],"explanation":["5 mm 이상 10 mm 이하는 양 끝 5와 10을 모두 포함해요.","5 mm·7.5 mm·10 mm는 들어가요.","10.5 mm만 10 mm보다 많아 빠져요."],"variant_rule":{"alt":[{"stem":"놀이 기구는 키 120 cm 이상 190 cm 미만인 사람만 탈 수 있어요. 다음 중 탈 수 없는 키는 어느 것인가요?","options":[{"t":"190 cm","correct":true},{"t":"120 cm","mis":"M5-2-u1-X01"},{"t":"189.9 cm","mis":"M5-2-u1-X17"},{"t":"150 cm","mis":"M5-2-u1-X17"}],"explanation":["120 cm 이상이라 120 cm는 들어가요.","190 cm 미만이라 190 cm는 빠져요.","탈 수 없는 키는 190 cm예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#3','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'sa','auto','37 이상 □ 미만인 자연수가 모두 6개예요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"37 이상 □ 미만인 자연수가 모두 6개예요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["37 이상이니 37부터 6개 — 37, 38, 39, 40, 41, 42예요.","□ 미만이라 □는 빠지니 42 다음 수가 □예요.","□ = 43이에요."],"variant_rule":{"alt":[{"stem":"□ 초과 50 이하인 자연수가 모두 8개예요. □에 알맞은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["50 이하이니 50부터 거꾸로 8개 — 50, 49, …, 43이에요.","□ 초과라 □는 빠지니 43 바로 앞 수가 □예요.","□ = 42예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#4','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'mc','auto','체감 온도 단계표를 「관심 29 °C 이상 31 °C 이하 · 주의 31 °C 이상 34 °C 이하」로 만들었다면 어떤 문제가 생길까요?',ARRAY['M5-2-u1-X01','M5-2-u1-X05','M5-2-u1-X16']::text[],true,'{"seq":4,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"체감 온도 단계표를 「관심 29 °C 이상 31 °C 이하 · 주의 31 °C 이상 34 °C 이하」로 만들었다면 어떤 문제가 생길까요?","options":[{"t":"31 °C가 두 단계에 함께 들어간다","correct":true},{"t":"31 °C가 어느 단계에도 들어가지 않는다","mis":"M5-2-u1-X01"},{"t":"아무 문제가 없다","mis":"M5-2-u1-X05"},{"t":"29 °C가 관심 단계에서 빠진다","mis":"M5-2-u1-X16"}],"explanation":["31 °C 이하에도, 31 °C 이상에도 31이 들어가요.","그러면 31 °C가 관심이기도 하고 주의이기도 해요.","그래서 진짜 표는 한쪽 끝만 넣어 겹치지 않게 짰어요."],"variant_rule":{"alt":[{"stem":"요금표를 「5 kg 미만 4000원 · 5 kg 초과 10 kg 이하 5000원」으로 만들었다면 어떤 문제가 생길까요?","options":[{"t":"5 kg인 소포의 요금을 정할 수 없다","correct":true},{"t":"5 kg인 소포가 두 요금에 함께 들어간다","mis":"M5-2-u1-X02"},{"t":"아무 문제가 없다","mis":"M5-2-u1-X05"},{"t":"10 kg인 소포가 빠진다","mis":"M5-2-u1-X16"}],"explanation":["5 kg 미만에도, 5 kg 초과에도 5 kg은 빠져요.","그러면 딱 5 kg인 소포는 어느 줄에도 없어요.","그래서 한쪽에는 「이하」나 「이상」을 써야 해요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#5','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'mc','auto','놀이공원 자유 이용권은 3세 미만 무료, 3세 이상 13세 미만 25000원, 13세 이상 40000원이에요. 동생(3세), 나(12세), 엄마가 함께 가면 모두 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"놀이공원 자유 이용권은 3세 미만 무료, 3세 이상 13세 미만 25000원, 13세 이상 40000원이에요. 동생(3세), 나(12세), 엄마가 함께 가면 모두 얼마인가요?","options":[{"t":"90000원","correct":true},{"t":"65000원","mis":"M5-2-u1-X02"},{"t":"105000원","mis":"M5-2-u1-X03"},{"t":"50000원","mis":"M5-2-u1-X16"}],"explanation":["동생 3세는 「3세 이상 13세 미만」 — 무료가 아니라 25000원이에요.","나 12세도 25000원, 엄마는 40000원이에요.","25000 + 25000 + 40000 = 90000원이에요."],"variant_rule":{"alt":[{"stem":"박물관 입장료는 13세 미만 1000원, 13세 이상 19세 미만 1500원, 19세 이상 2000원이에요. 은우(11세)와 형(19세)의 입장료는 모두 얼마인가요?","options":[{"t":"3000원","correct":true},{"t":"2500원","mis":"M5-2-u1-X02"},{"t":"3500원","mis":"M5-2-u1-X03"},{"t":"2000원","mis":"M5-2-u1-X16"}],"explanation":["은우 11세는 13세 미만 — 1000원이에요.","형 19세는 「13세 이상 19세 미만」에 빠지고 「19세 이상」 — 2000원이에요.","1000 + 2000 = 3000원이에요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#6','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'error','auto','「5 이상 10 미만인 자연수」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u1-X05','M5-2-u1-X17']::text[],true,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":3,"kind":"error","stem":"「5 이상 10 미만인 자연수」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「5, 6, 7, 8, 9, 10으로 모두 6개야.」","correct":true,"mis_target":"M5-2-u1-X05"},{"t":"라온 — 「가장 작은 수는 5야.」","mis":"M5-2-u1-X17"},{"t":"소이 — 「가장 큰 수는 9야.」","mis":"M5-2-u1-X17"}],"explanation":["5 이상이라 5는 들어가요.","10 미만이라 10은 빠져요.","5부터 9까지 5개예요 — 태윤이가 10까지 넣었어요."],"variant_rule":{"alt":[{"stem":"「20 초과 25 이하인 자연수」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시하 — 「20부터 25까지 모두 6개야.」","correct":true,"mis_target":"M5-2-u1-X05"},{"t":"우진 — 「가장 작은 수는 21이야.」","mis":"M5-2-u1-X17"},{"t":"예나 — 「가장 큰 수는 25야.」","mis":"M5-2-u1-X17"}],"explanation":["20 초과라 20은 빠져요.","25 이하라 25는 들어가요.","21부터 25까지 5개예요 — 시하가 20을 넣었어요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#7','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'mc','auto','「3 이상 8 미만인 수」와 「5 초과 10 이하인 수」에 모두 들어가는 자연수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X05']::text[],true,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"「3 이상 8 미만인 수」와 「5 초과 10 이하인 수」에 모두 들어가는 자연수를 모두 고른 것은 어느 것인가요?","options":[{"t":"6, 7","correct":true},{"t":"5, 6, 7","mis":"M5-2-u1-X02"},{"t":"6, 7, 8","mis":"M5-2-u1-X02"},{"t":"3, 4, 5, 6, 7, 8, 9, 10","mis":"M5-2-u1-X05"}],"explanation":["첫째 범위의 자연수는 3, 4, 5, 6, 7이에요.","둘째 범위의 자연수는 6, 7, 8, 9, 10이에요.","두 곳 모두에 들어가는 것은 6, 7이에요."],"variant_rule":{"alt":[{"stem":"「10 초과 15 이하인 수」와 「12 이상 20 미만인 수」에 모두 들어가는 자연수를 모두 고른 것은 어느 것인가요?","options":[{"t":"12, 13, 14, 15","correct":true},{"t":"11, 12, 13, 14, 15","mis":"M5-2-u1-X05"},{"t":"13, 14, 15","mis":"M5-2-u1-X01"},{"t":"12, 13, 14","mis":"M5-2-u1-X01"}],"explanation":["첫째 범위의 자연수는 11~15예요.","둘째 범위의 자연수는 12~19예요.","두 곳 모두에 들어가는 것은 12, 13, 14, 15예요."]}]}}'::jsonb),
('g5_2_math_u1_L04_challenge#8','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',4,'essay','teacher','어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 단계마다 한쪽 끝만 「이상」으로 넣고 다른 끝은 「미만」으로 뺀 까닭을 쓰고, 30.9 °C와 31 °C가 각각 어느 단계인지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 단계마다 한쪽 끝만 「이상」으로 넣고 다른 끝은 「미만」으로 뺀 까닭을 쓰고, 30.9 °C와 31 °C가 각각 어느 단계인지 설명하세요.","answer_guide":{"answer":"예: 한쪽 끝만 넣어야 단계가 서로 겹치지 않고 빈틈도 없어 어떤 온도든 딱 한 단계에만 들어간다. 30.9 °C는 29 이상 31 미만이라 관심, 31 °C는 31 이상 34 미만이라 주의이다.","scoring_points":["겹치지 않고 빈틈없이 나누려는 까닭을 썼는가","30.9 °C를 관심으로 판단했는가","31 °C를 주의로 판단했는가"]},"explanation":["경계를 한쪽에만 넣으면 겹침도 빈틈도 없어요.","30.9 °C — 관심이에요.","31 °C — 관심에서 빠지고 주의에 들어가요."]}'::jsonb),
('g5_2_math_u1_L04_challenge#9','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',4,'essay','teacher','우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 20 kg인 소포와 20.5 kg인 소포의 요금을 각각 구하고, 0.5 kg 차이인데 요금이 달라지는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 20 kg인 소포와 20.5 kg인 소포의 요금을 각각 구하고, 0.5 kg 차이인데 요금이 달라지는 까닭을 쓰세요.","answer_guide":{"answer":"예: 20 kg은 「10 kg 초과 20 kg 이하」라 7000원, 20.5 kg은 「20 kg 초과 25 kg 이하」라 9000원이다. 20 kg이 경곗값이라 20 kg까지는 이하 쪽에 들어가고 20 kg보다 조금이라도 무거우면 다음 범위로 넘어가기 때문이다.","scoring_points":["20 kg 요금 7000원을 구했는가","20.5 kg 요금 9000원을 구했는가","경곗값 20 kg을 넘는지에 따라 범위가 바뀐다는 까닭을 썼는가"]},"explanation":["20 kg — 이하라 7000원이에요.","20.5 kg — 초과라 9000원이에요.","경곗값을 넘으면 다음 줄로 넘어가요."]}'::jsonb),
('g5_2_math_u1_L04_challenge#10','math',5,2,'u1','L04','g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',4,'mc','auto','우리 반 학생 수는 25명 이상 30명 미만이고 홀수예요. 6명씩 모둠을 만들면 1명이 남아요. 우리 반 학생은 몇 명인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X05']::text[],true,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":4,"kind":"mc","stem":"우리 반 학생 수는 25명 이상 30명 미만이고 홀수예요. 6명씩 모둠을 만들면 1명이 남아요. 우리 반 학생은 몇 명인가요?","options":[{"t":"25명","correct":true},{"t":"27명","mis":"M5-2-u1-X16"},{"t":"29명","mis":"M5-2-u1-X16"},{"t":"31명","mis":"M5-2-u1-X05"}],"explanation":["25명 이상 30명 미만인 홀수는 25, 27, 29예요.","6으로 나누면 25 → 1 남음, 27 → 3 남음, 29 → 5 남음이에요.","조건을 모두 맞는 것은 25명이에요."],"variant_rule":{"alt":[{"stem":"상자 속 사과는 40개 초과 50개 이하이고 짝수예요. 7개씩 담으면 1개가 남아요. 사과는 몇 개인가요?","options":[{"t":"50개","correct":true},{"t":"42개","mis":"M5-2-u1-X16"},{"t":"44개","mis":"M5-2-u1-X16"},{"t":"36개","mis":"M5-2-u1-X05"}],"explanation":["40개 초과 50개 이하인 짝수는 42, 44, 46, 48, 50이에요.","7로 나누면 42 → 0, 44 → 2, 46 → 4, 48 → 6, 50 → 1 남음이에요.","조건을 모두 맞는 것은 50개예요."]}]}}'::jsonb),
('g5_2_math_u1_L05_basic#1','math',5,2,'u1','L05','g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',1,'mc','auto','학생 543명에게 친환경 가방을 1개씩 나누어 주려고 해요. 가방은 10개 묶음으로만 판다면 최소 몇 개를 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"학생 543명에게 친환경 가방을 1개씩 나누어 주려고 해요. 가방은 10개 묶음으로만 판다면 최소 몇 개를 사야 하나요?","options":[{"t":"550개","correct":true},{"t":"540개","mis":"M5-2-u1-X13"},{"t":"55개","mis":"M5-2-u1-X14"},{"t":"600개","mis":"M5-2-u1-X09"}],"explanation":["54묶음은 540개라 543명에게는 모자라요.","모자라면 안 되니 55묶음 — 올림이에요.","543을 올림하여 십의 자리까지 나타낸 550개를 사야 해요."],"variant_rule":{"alt":[{"stem":"학생 278명에게 친환경 가방을 1개씩 나누어 주려고 해요. 가방은 10개 묶음으로만 판다면 최소 몇 개를 사야 하나요?","options":[{"t":"280개","correct":true},{"t":"270개","mis":"M5-2-u1-X13"},{"t":"28개","mis":"M5-2-u1-X14"},{"t":"300개","mis":"M5-2-u1-X09"}],"explanation":["27묶음은 270개라 278명에게는 모자라요.","모자라면 안 되니 28묶음 — 올림이에요.","278을 올림하여 십의 자리까지 나타낸 280개를 사야 해요."]},{"stem":"학생 1362명에게 친환경 가방을 1개씩 나누어 주려고 해요. 가방은 100개 묶음으로만 판다면 최소 몇 개를 사야 하나요?","options":[{"t":"1400개","correct":true},{"t":"1300개","mis":"M5-2-u1-X13"},{"t":"14개","mis":"M5-2-u1-X14"},{"t":"2000개","mis":"M5-2-u1-X09"}],"explanation":["13묶음은 1300개라 1362명에게는 모자라요.","모자라면 안 되니 14묶음 — 올림이에요.","1362를 올림하여 백의 자리까지 나타낸 1400개를 사야 해요."]}]}}'::jsonb),
