('g5_2_math_u1_L05_basic#9','math',5,2,'u1','L05','g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'ox','auto','올림할 때 구하려는 자리 아래 수가 모두 0이면 올리지 않고 그대로 써요.',ARRAY['M5-2-u1-X07']::text[],true,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":2,"kind":"ox","stem":"올림할 때 구하려는 자리 아래 수가 모두 0이면 올리지 않고 그대로 써요.","answer":"O","reason_options":[{"t":"아래 수가 모두 0이면 올릴 것이 없어 이미 모자라지 않아서","correct":true},{"t":"올림은 언제나 한 칸 올리는 방법이라서","mis":"M5-2-u1-X07"}],"mis":"M5-2-u1-X07","explanation":["올림은 모자라지 않게 하려고 아래 수를 올려요.","아래가 모두 0이면 이미 딱 맞아 모자라지 않아요.","예: 2500을 올림하여 백의 자리까지 → 2500이에요."],"variant_rule":{"alt":[{"stem":"6000을 올림하여 천의 자리까지 나타내면 7000이에요.","answer":"X","reason_options":[{"t":"천의 자리 아래가 000이라 올릴 것이 없어 6000 그대로라서","correct":true},{"t":"올림은 언제나 한 칸 올리는 방법이라서","mis":"M5-2-u1-X07"}],"explanation":["6000에서 천의 자리 아래는 000이에요.","올릴 것이 없으니 그대로예요.","6000 → 6000이에요."]}]}}'::jsonb),
