('g5_2_math_u2_L02_challenge#6','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'mc','auto','⟨3/4⟩ × 2를 계산할 때 약분은 언제 해야 하나요?',ARRAY['M5-2-u2-X13','M5-2-u2-X12']::text[],true,'{"seq":6,"concept":"M5-2-u2-C2","difficulty":3,"kind":"mc","stem":"⟨3/4⟩ × 2를 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩이에요.","곱하기 전에 4와 2를 2로 약분해도 ⟨3/2⟩ × 1 = ⟨3/2⟩이에요.","언제 약분하든 값은 같아요."],"variant_rule":{"alt":[{"stem":"⟨5/6⟩ × 4를 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨5/6⟩ × 4 = ⟨20/6⟩ = ⟨10/3⟩이에요.","곱하기 전에 6과 4를 2로 약분해도 ⟨5/3⟩ × 2 = ⟨10/3⟩이에요.","언제 약분하든 값은 같아요."]},{"stem":"⟨7/12⟩ × 8을 계산할 때 약분은 언제 해야 하나요?","options":[{"t":"곱하기 전·곱하는 중·곱한 뒤 언제 해도 값이 같다","correct":true},{"t":"반드시 곱한 뒤에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"반드시 곱하기 전에만 해야 한다","mis":"M5-2-u2-X13"},{"t":"분수와 자연수를 곱할 때는 약분할 수 없다","mis":"M5-2-u2-X12"}],"explanation":["곱한 뒤 약분: ⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩예요.","곱하기 전에 12와 8을 4로 약분해도 ⟨7/3⟩ × 2 = ⟨14/3⟩예요.","언제 약분하든 값은 같아요."]}]}}'::jsonb),
('g5_2_math_u2_L02_challenge#7','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',3,'ox','auto','⟨2/5⟩ × 4를 계산할 때는 분모에도 4를 곱해요.',ARRAY['M5-2-u2-X01']::text[],true,'{"seq":7,"concept":"M5-2-u2-C2","difficulty":3,"kind":"ox","stem":"⟨2/5⟩ × 4를 계산할 때는 분모에도 4를 곱해요.","answer":"X","reason_options":[{"t":"한 칸의 크기 ⟨1/5⟩은 그대로이고 칸의 수만 늘어나 분모는 그대로이므로","correct":true},{"t":"분수에 곱할 때는 분모와 분자에 똑같이 곱하므로","mis":"M5-2-u2-X01"}],"mis":"M5-2-u2-X01","explanation":["⟨2/5⟩ × 4 = ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩예요.","분모가 같은 분수의 덧셈이라 분모는 그대로예요.","⟨2/5⟩ × 4 = ⟨8/5⟩ — 분모는 5예요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩ × 3의 분자는 5예요.","answer":"X","reason_options":[{"t":"분자와 자연수를 곱해 2 × 3 = 6이므로","correct":true},{"t":"분자와 자연수를 더해 2 + 3 = 5이므로","mis":"M5-2-u2-X15"}],"explanation":["(진분수)×(자연수)는 분자와 자연수를 곱해요.","2 × 3 = 6이에요.","⟨2/9⟩ × 3 = ⟨6/9⟩ — 분자는 6이에요."]},{"stem":"⟨3/4⟩ × 2는 곱하기 전에 약분해도, 곱한 뒤에 약분해도 값이 같아요.","answer":"O","reason_options":[{"t":"곱하기 전·중·후 어느 때 약분해도 ⟨3/2⟩으로 같으므로","correct":true},{"t":"곱한 뒤에만 약분할 수 있으므로","mis":"M5-2-u2-X13"}],"explanation":["곱한 뒤 약분하면 ⟨3/4⟩ × 2 = ⟨6/4⟩ = ⟨3/2⟩이에요.","곱하기 전에 4와 2를 약분해도 ⟨3/2⟩ × 1 = ⟨3/2⟩이에요.","약분은 언제 해도 값이 같아요."]}]}}'::jsonb),
('g5_2_math_u2_L02_challenge#8','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'sa','auto','⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u2-C2","difficulty":4,"kind":"sa","stem":"⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로이고 분자만 3에서 15로 바뀌었어요.","분자와 □를 곱해 15가 되어야 해요 — 3 × 5 = 15.","그래서 □는 5예요."],"mis":"M5-2-u2-X01","variant_rule":{"alt":[{"stem":"⟨2/9⟩ × □ = ⟨8/9⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["분모는 그대로이고 분자만 2에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 2 × 4 = 8.","그래서 □는 4예요."]},{"stem":"⟨4/11⟩ × □ = ⟨8/11⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모는 그대로이고 분자만 4에서 8로 바뀌었어요.","분자와 □를 곱해 8이 되어야 해요 — 4 × 2 = 8.","그래서 □는 2예요."]}]}}'::jsonb),
('g5_2_math_u2_L02_challenge#9','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'match','auto','곱셈식과 계산 결과를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u2-C2","difficulty":4,"kind":"match","stem":"곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨1/9⟩ × 5","r":"⟨5/9⟩"},{"l":"⟨5/6⟩ × 7","r":"⟨5 5/6⟩"},{"l":"⟨7/12⟩ × 8","r":"⟨4 2/3⟩"}],"mis":"M5-2-u2-X01","explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨1/9⟩ × 5 = ⟨5/9⟩, ⟨5/6⟩ × 7 = ⟨35/6⟩ = ⟨5 5/6⟩, ⟨7/12⟩ × 8 = ⟨56/12⟩ = ⟨14/3⟩ = ⟨4 2/3⟩예요.","분모에 자연수를 곱하지 않도록 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨2/5⟩ × 4","r":"⟨1 3/5⟩"},{"l":"⟨1/4⟩ × 3","r":"⟨3/4⟩"},{"l":"⟨3/10⟩ × 3","r":"⟨9/10⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩, ⟨1/4⟩ × 3 = ⟨3/4⟩, ⟨3/10⟩ × 3 = ⟨9/10⟩예요.","분모에 자연수를 곱하지 않도록 해요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 계산 결과를 알맞게 이으세요.","pairs":[{"l":"⟨4/7⟩ × 3","r":"⟨1 5/7⟩"},{"l":"⟨2/9⟩ × 6","r":"⟨1 1/3⟩"},{"l":"⟨5/8⟩ × 2","r":"⟨1 1/4⟩"}],"explanation":["분모는 그대로 두고 분자와 자연수를 곱해요.","⟨4/7⟩ × 3 = ⟨12/7⟩ = ⟨1 5/7⟩, ⟨2/9⟩ × 6 = ⟨12/9⟩ = ⟨4/3⟩ = ⟨1 1/3⟩, ⟨5/8⟩ × 2 = ⟨10/8⟩ = ⟨5/4⟩ = ⟨1 1/4⟩이에요.","분모에 자연수를 곱하지 않도록 해요."]}]}}'::jsonb),
('g5_2_math_u2_L02_challenge#10','math',5,2,'u2','L02','g5_2_math_u2_L02_challenge','lesson_challenge','M5-2-u2-C2',4,'essay','teacher','⟨2/5⟩ × 4를 계산할 때 분모 5는 그대로 두고 분자에만 4를 곱하는 까닭을 수직선(또는 덧셈)을 이용해 설명하고, 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u2-C2","difficulty":4,"kind":"essay","stem":"⟨2/5⟩ × 4를 계산할 때 분모 5는 그대로 두고 분자에만 4를 곱하는 까닭을 수직선(또는 덧셈)을 이용해 설명하고, 계산해 보세요.","answer_guide":{"answer":"예: ⟨2/5⟩ × 4는 ⟨2/5⟩를 4번 더한 것이다. 수직선의 0에서 ⟨2/5⟩씩 4번 뛰어 세면 ⟨1/5⟩짜리 칸이 2 × 4 = 8개가 된다. 한 칸의 크기 ⟨1/5⟩은 그대로이고 칸의 수만 늘어났으므로 분모는 그대로 두고 분자만 곱한다. ⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이다.","scoring_points":["같은 수를 4번 더한 것(뛰어 세기)으로 설명했는가","한 칸의 크기는 그대로라 분모가 그대로임을 밝혔는가","⟨8/5⟩(= ⟨1 3/5⟩)을 구했는가"]},"explanation":["⟨2/5⟩ × 4 = ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩ + ⟨2/5⟩예요.","⟨1/5⟩ 칸이 8개 — 칸 크기는 그대로예요.","⟨2/5⟩ × 4 = ⟨8/5⟩ = ⟨1 3/5⟩이에요."]}'::jsonb),
('g5_2_math_u2_L03_basic#1','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','⟨1 1/4⟩을 가분수로 나타내면 어느 것인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X04']::text[],true,'{"seq":1,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨5/4⟩","correct":true},{"t":"⟨4/5⟩","mis":"M5-2-u2-X17"},{"t":"⟨2/4⟩","mis":"M5-2-u2-X04"},{"t":"⟨1/4⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨4/4⟩예요 — 1 × 4 = 4.","여기에 ⟨1/4⟩을 더하면 분자는 4 + 1 = 5예요.","⟨1 1/4⟩ = ⟨5/4⟩예요."],"variant_rule":{"alt":[{"stem":"⟨1 3/5⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M5-2-u2-X17"},{"t":"⟨4/5⟩","mis":"M5-2-u2-X04"},{"t":"⟨3/5⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨5/5⟩예요 — 1 × 5 = 5.","여기에 ⟨3/5⟩을 더하면 분자는 5 + 3 = 8이에요.","⟨1 3/5⟩ = ⟨8/5⟩이에요."]},{"stem":"⟨2 1/3⟩을 가분수로 나타내면 어느 것인가요?","options":[{"t":"⟨7/3⟩","correct":true},{"t":"⟨3/7⟩","mis":"M5-2-u2-X17"},{"t":"⟨3/3⟩","mis":"M5-2-u2-X04"},{"t":"⟨2/3⟩","mis":"M5-2-u2-X04"}],"explanation":["자연수 2는 ⟨6/3⟩이에요 — 2 × 3 = 6.","여기에 ⟨1/3⟩을 더하면 분자는 6 + 1 = 7이에요.","⟨2 1/3⟩ = ⟨7/3⟩이에요."]}]}}'::jsonb),
('g5_2_math_u2_L03_basic#2','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'mc','auto','⟨1 1/4⟩ × 3을 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u2-X05','M5-2-u2-X15']::text[],true,'{"seq":2,"concept":"M5-2-u2-C3","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩ × 3을 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 3 + ⟨1/4⟩ × 3","correct":true},{"t":"1 × 3 + ⟨1/4⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨1/4⟩ × 3","mis":"M5-2-u2-X05"},{"t":"1 × ⟨1/4⟩ × 3","mis":"M5-2-u2-X15"}],"explanation":["⟨1 1/4⟩은 1 + ⟨1/4⟩이에요.","자연수 부분과 분수 부분에 모두 3을 곱해 더해요.","1 × 3 + ⟨1/4⟩ × 3 = 3 + ⟨3/4⟩ = ⟨3 3/4⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨2 1/3⟩ × 5를 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 5 + ⟨1/3⟩ × 5","correct":true},{"t":"2 × 5 + ⟨1/3⟩","mis":"M5-2-u2-X05"},{"t":"2 + ⟨1/3⟩ × 5","mis":"M5-2-u2-X05"},{"t":"2 × ⟨1/3⟩ × 5","mis":"M5-2-u2-X15"}],"explanation":["⟨2 1/3⟩은 2 + ⟨1/3⟩이에요.","자연수 부분과 분수 부분에 모두 5를 곱해 더해요.","2 × 5 + ⟨1/3⟩ × 5 = 10 + ⟨1 2/3⟩ = ⟨11 2/3⟩예요."]},{"stem":"⟨1 3/5⟩ × 2를 대분수의 자연수 부분과 분수 부분으로 갈라 계산하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 2 + ⟨3/5⟩ × 2","correct":true},{"t":"1 × 2 + ⟨3/5⟩","mis":"M5-2-u2-X05"},{"t":"1 + ⟨3/5⟩ × 2","mis":"M5-2-u2-X05"},{"t":"1 × ⟨3/5⟩ × 2","mis":"M5-2-u2-X15"}],"explanation":["⟨1 3/5⟩은 1 + ⟨3/5⟩이에요.","자연수 부분과 분수 부분에 모두 2를 곱해 더해요.","1 × 2 + ⟨3/5⟩ × 2 = 2 + ⟨1 1/5⟩ = ⟨3 1/5⟩이에요."]}]}}'::jsonb),
('g5_2_math_u2_L03_basic#3','math',5,2,'u2','L03','g5_2_math_u2_L03_basic','lesson_basic','M5-2-u2-C3',1,'ox','auto','⟨1 1/4⟩ × 3은 ⟨1 1/4⟩ + ⟨1 1/4⟩ + ⟨1 1/4⟩과 같아요.',ARRAY['M5-2-u2-X15']::text[],true,'{"seq":3,"concept":"M5-2-u2-C3","difficulty":1,"kind":"ox","stem":"⟨1 1/4⟩ × 3은 ⟨1 1/4⟩ + ⟨1 1/4⟩ + ⟨1 1/4⟩과 같아요.","answer":"O","reason_options":[{"t":"같은 수를 세 번 더한 것을 곱셈으로 적은 것이므로","correct":true},{"t":"대분수는 곱셈으로 적을 수 없으므로","mis":"M5-2-u2-X15"}],"mis":"M5-2-u2-X15","explanation":["⟨1 1/4⟩씩 세 번 뛰어 세면 ⟨1 1/4⟩ → ⟨2 2/4⟩ → ⟨3 3/4⟩이에요.","⟨1 1/4⟩ × 3 = ⟨3 3/4⟩이에요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"⟨1 3/5⟩을 가분수로 나타내면 ⟨8/5⟩이에요.","answer":"O","reason_options":[{"t":"1 × 5 + 3 = 8이므로","correct":true},{"t":"1 + 3 + 5 = 9이므로","mis":"M5-2-u2-X04"}],"explanation":["자연수 1은 ⟨5/5⟩예요.","⟨5/5⟩ + ⟨3/5⟩ = ⟨8/5⟩이에요.","그래서 맞아요."]},{"stem":"대분수에 자연수를 곱하는 방법은 가르기와 가분수로 고치기 두 가지가 있고, 답은 같아요.","answer":"O","reason_options":[{"t":"같은 수를 다르게 계산했을 뿐이므로","correct":true},{"t":"가분수로 고치면 답이 더 커지므로","mis":"M5-2-u2-X12"}],"explanation":["가르기: 2 × 5 + ⟨1/3⟩ × 5 = ⟨11 2/3⟩예요.","가분수: ⟨7/3⟩ × 5 = ⟨35/3⟩ = ⟨11 2/3⟩예요.","두 방법 모두 ⟨11 2/3⟩ — 맞아요."]}]}}'::jsonb),
