('g5_2_math_u2_L04_basic#3','math',5,2,'u2','L04','g5_2_math_u2_L04_basic','lesson_basic','M5-2-u2-C4',1,'ox','auto','「6의 ⟨1/3⟩」과 「6 × ⟨1/3⟩」은 같은 말이에요.',ARRAY['M5-2-u2-X07']::text[],true,'{"seq":3,"concept":"M5-2-u2-C4","difficulty":1,"kind":"ox","stem":"「6의 ⟨1/3⟩」과 「6 × ⟨1/3⟩」은 같은 말이에요.","answer":"O","reason_options":[{"t":"둘 다 6을 똑같이 3으로 나눈 것 중의 1이므로","correct":true},{"t":"「의」는 덧셈을 뜻하므로","mis":"M5-2-u2-X07"}],"mis":"M5-2-u2-X07","explanation":["6을 똑같이 3으로 나누면 한 묶음은 2예요.","6 × ⟨1/3⟩ = 2예요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"12 × ⟨1/4⟩은 12를 4로 나눈 것과 같아요.","answer":"O","reason_options":[{"t":"12의 ⟨1/4⟩은 12를 똑같이 4로 나눈 것 중의 1이므로","correct":true},{"t":"12에 4를 곱한 것이므로","mis":"M5-2-u2-X07"}],"explanation":["12를 똑같이 4로 나누면 한 묶음은 3이에요.","12 × ⟨1/4⟩ = 3이에요.","12 ÷ 4 = 3 — 맞아요."]},{"stem":"⟨3/5⟩ × 2와 2 × ⟨3/5⟩의 계산 결과는 같아요.","answer":"O","reason_options":[{"t":"뜻은 달라도 둘 다 ⟨6/5⟩이므로","correct":true},{"t":"곱하는 순서가 바뀌면 결과도 바뀌므로","mis":"M5-2-u2-X15"}],"explanation":["⟨3/5⟩ × 2 = ⟨6/5⟩이에요.","2 × ⟨3/5⟩ = ⟨6/5⟩이에요.","그래서 맞아요."]}]}}'::jsonb),
