('g5_2_math_u2_review_b#6','math',5,2,'u2','','g5_2_math_u2_review_b','unit_review','M5-2-u2-C6',1,'mc','auto','⟨1/2⟩ × ⟨1/9⟩을 계산하면 얼마인가요?',ARRAY['M5-2-u2-X10']::text[],true,'{"seq":6,"concept":"M5-2-u2-C6","difficulty":1,"kind":"mc","stem":"⟨1/2⟩ × ⟨1/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/18⟩","correct":true},{"t":"⟨2/18⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/11⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/11⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 2등분 한 것 중의 1을 다시 9등분 해요.","전체는 2 × 9 = 18칸이 되고, 그중의 1칸이에요.","⟨1/2⟩ × ⟨1/9⟩ = ⟨1/18⟩이에요."],"variant_rule":{"alt":[{"stem":"⟨1/6⟩ × ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/24⟩","correct":true},{"t":"⟨2/24⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 6등분 한 것 중의 1을 다시 4등분 해요.","전체는 6 × 4 = 24칸이 되고, 그중의 1칸이에요.","⟨1/6⟩ × ⟨1/4⟩ = ⟨1/24⟩이에요."]},{"stem":"⟨1/7⟩ × ⟨1/3⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/21⟩","correct":true},{"t":"⟨2/21⟩","mis":"M5-2-u2-X10"},{"t":"⟨1/10⟩","mis":"M5-2-u2-X10"},{"t":"⟨2/10⟩","mis":"M5-2-u2-X10"}],"explanation":["전체를 7등분 한 것 중의 1을 다시 3등분 해요.","전체는 7 × 3 = 21칸이 되고, 그중의 1칸이에요.","⟨1/7⟩ × ⟨1/3⟩ = ⟨1/21⟩이에요."]}]}}'::jsonb),
