('g5_2_math_u2_review_d#22','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C8',3,'mc','auto','준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?',ARRAY['M5-2-u2-X17','M5-2-u2-X16']::text[],true,'{"seq":22,"concept":"M5-2-u2-C8","difficulty":3,"kind":"mc","stem":"준기네 마을은 주민 85명 가운데 ⟨3/5⟩ 이상, 도윤이네 마을은 주민 96명 가운데 ⟨2/3⟩ 이상이 동의해야 해요. 지금까지 각각 44명, 55명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"도윤이네 마을","correct":true},{"t":"준기네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["준기네 마을: 85 × ⟨3/5⟩ = 51, 51 − 44 = 7(명)이에요.","도윤이네 마을: 96 × ⟨2/3⟩ = 64, 64 − 55 = 9(명)이에요.","도윤이네 마을에서 더 많이 더 동의해야 해요."],"variant_rule":{"alt":[{"stem":"서연이네 마을은 주민 90명 가운데 ⟨2/3⟩ 이상, 준기네 마을은 주민 80명 가운데 ⟨3/5⟩ 이상이 동의해야 해요. 지금까지 각각 52명, 39명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"준기네 마을","correct":true},{"t":"서연이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["서연이네 마을: 90 × ⟨2/3⟩ = 60, 60 − 52 = 8(명)이에요.","준기네 마을: 80 × ⟨3/5⟩ = 48, 48 − 39 = 9(명)이에요.","준기네 마을에서 더 많이 더 동의해야 해요."]},{"stem":"하린이네 마을은 주민 72명 가운데 ⟨3/4⟩ 이상, 도윤이네 마을은 주민 84명 가운데 ⟨3/4⟩ 이상이 동의해야 해요. 지금까지 각각 47명, 60명이 동의했어요. 더 많은 사람이 더 동의해야 하는 마을은 어디인가요?","options":[{"t":"하린이네 마을","correct":true},{"t":"도윤이네 마을","mis":"M5-2-u2-X17"},{"t":"두 마을이 같다","mis":"M5-2-u2-X16"},{"t":"알 수 없다","mis":"M5-2-u2-X16"}],"explanation":["하린이네 마을: 72 × ⟨3/4⟩ = 54, 54 − 47 = 7(명)이에요.","도윤이네 마을: 84 × ⟨3/4⟩ = 63, 63 − 60 = 3(명)이에요.","하린이네 마을에서 더 많이 더 동의해야 해요."]}]}}'::jsonb),
('g5_2_math_u2_review_d#23','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C7',4,'sa','auto','5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M5-2-u2-C7","difficulty":4,"kind":"sa","stem":"5학년 학생 96명 가운데 ⟨3/4⟩이 남학생이고, 남학생 가운데 ⟨5/8⟩가 야구를 좋아해요. 야구를 좋아하는 5학년 남학생은 몇 명인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["남학생은 96 × ⟨3/4⟩ = 72명이에요.","그 가운데 ⟨5/8⟩니 72 × ⟨5/8⟩ = 45명이에요.","한 번에 96 × ⟨3/4⟩ × ⟨5/8⟩ = 45로 구해도 같아요."],"mis":"M5-2-u2-X15","variant_rule":{"alt":[{"stem":"⟨3/8⟩ × □ = ⟨15/8⟩일 때 □에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모는 그대로이고 분자만 3에서 15로 바뀌었어요.","분자와 □를 곱해 15가 되어야 해요 — 3 × 5 = 15.","그래서 □는 5예요."]},{"stem":"20 × ⟨□/4⟩ = 15일 때 □에 알맞은 수는 얼마인가요? (□는 분자예요) 숫자로 쓰세요.","answer":["3"],"explanation":["20을 똑같이 4로 나누면 한 묶음은 5예요.","3묶음이 15니 □ = 15 ÷ 5 = 3이에요.","20 × ⟨3/4⟩ = 15 — 맞아요."]}]}}'::jsonb),
('g5_2_math_u2_review_d#24','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C5',4,'essay','teacher','가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭의 넓이를 세로를 둘로 갈라 구하는 방법으로 설명하고, 가분수로 고쳐 구한 값과 같은지 확인해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u2-C5","difficulty":4,"kind":"essay","stem":"가로가 2 m, 세로가 ⟨1 2/5⟩ m인 직사각형 모양 텃밭의 넓이를 세로를 둘로 갈라 구하는 방법으로 설명하고, 가분수로 고쳐 구한 값과 같은지 확인해 보세요.","answer_guide":{"answer":"예: 세로 ⟨1 2/5⟩ m를 1 m와 ⟨2/5⟩ m로 가르면, 세로 1 m인 부분은 2 × 1 = 2 m², 세로 ⟨2/5⟩ m인 부분은 2 × ⟨2/5⟩ = ⟨4/5⟩ m²이다. 둘을 더하면 2 + ⟨4/5⟩ = ⟨2 4/5⟩ m²이다. 가분수로 고치면 2 × ⟨7/5⟩ = ⟨14/5⟩ = ⟨2 4/5⟩ m²로 같다.","scoring_points":["세로를 1과 ⟨2/5⟩로 갈라 두 넓이를 구했는가","⟨2 4/5⟩ m²를 구했는가","가분수로 고쳐 구한 값과 같음을 확인했는가"]},"explanation":["2 × 1 = 2, 2 × ⟨2/5⟩ = ⟨4/5⟩예요.","2 + ⟨4/5⟩ = ⟨2 4/5⟩ m²예요.","2 × ⟨7/5⟩ = ⟨2 4/5⟩ — 같아요."]}'::jsonb),
('g5_2_math_u2_review_d#25','math',5,2,'u2','','g5_2_math_u2_review_d','unit_review','M5-2-u2-C1',4,'essay','teacher','여울이, 순달이, 달곰이가 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유의 양을 덧셈식과 곱셈식으로 각각 나타내고, 모두 몇 L인지 구해 보세요. 그리고 20명이 남겼다면 어떤 식이 더 편한지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u2-C1","difficulty":4,"kind":"essay","stem":"여울이, 순달이, 달곰이가 딸기우유를 ⟨3/10⟩ L씩 남겼어요. 남긴 딸기우유의 양을 덧셈식과 곱셈식으로 각각 나타내고, 모두 몇 L인지 구해 보세요. 그리고 20명이 남겼다면 어떤 식이 더 편한지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 덧셈식은 ⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩이고 곱셈식은 ⟨3/10⟩ × 3이다. 분모는 그대로 두고 분자끼리 더하면 ⟨9/10⟩ L이다. 20명이 남겼다면 ⟨3/10⟩을 20번 더해야 해서 덧셈식이 너무 길어지므로, ⟨3/10⟩ × 20처럼 곱셈식으로 적는 것이 한 줄로 끝나 더 편하다.","scoring_points":["덧셈식과 곱셈식 ⟨3/10⟩ × 3을 모두 썼는가","⟨9/10⟩ L를 구했는가","여러 번 더할 때는 곱셈식이 짧아 편하다고 설명했는가"]},"explanation":["⟨3/10⟩ + ⟨3/10⟩ + ⟨3/10⟩ = ⟨3/10⟩ × 3이에요.","분자끼리 더하면 ⟨9/10⟩ L예요.","20번이면 곱셈식이 한 줄로 끝나요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M5-2-u3-C1','math',5,2,'u3',2,'도형의 이동과 포개어 보기 — 밀기·뒤집기·돌리기를 해도 자리와 방향만 바뀔 뿐 변의 길이·각의 크기·모양·크기는 그대로임을 되짚고, 두 도형이 꼭 같은지는 눈으로가 아니라 포개어 보거나 재어 보아 확인하기',ARRAY['6수03-03']::text[],1),
('M5-2-u3-C2','math',5,2,'u3',2,'도형의 합동 — 모양과 크기가 같아 포개었을 때 완전히 겹치는 두 도형을 서로 합동이라 하고, 밀거나 뒤집거나 돌려서 겹쳐도 합동이지만 크기가 다르거나 넓이만 같은 도형은 합동이 아님을 알기',ARRAY['6수03-03']::text[],2),
('M5-2-u3-C3','math',5,2,'u3',3,'대응점·대응변·대응각 — 합동인 두 도형을 포개었을 때 겹치는 점·변·각을 이름 차례가 아니라 겹치는 자리로 찾고, 대응변의 길이와 대응각의 크기가 같음을 이용해 재지 않고 길이·각도·둘레를 구하기',ARRAY['6수03-04']::text[],3),
('M5-2-u3-C4','math',5,2,'u3',4,'선대칭도형과 대칭축 — 한 직선을 따라 접었을 때 완전히 겹치는 도형과 그 직선(대칭축)을 알고, 대칭축이 도형마다 여러 개일 수 있으며 넓이를 반으로 나누는 선이 모두 대칭축은 아님을 알기',ARRAY['6수03-05']::text[],4),
('M5-2-u3-C5','math',5,2,'u3',5,'선대칭도형의 성질 — 대칭축으로 접어 겹치는 대응점·대응변·대응각을 찾고, 대응변의 길이와 대응각의 크기가 같으며 대칭축은 대응점을 이은 선분을 수직으로 이등분함을 알기',ARRAY['6수03-05']::text[],5),
('M5-2-u3-C6','math',5,2,'u3',6,'선대칭도형 그리기 — 각 꼭짓점에서 대칭축까지의 거리를 재어 대칭축과 수직인 방향으로 반대쪽에 같은 거리만큼 대응점을 찍고(대칭축 위의 점은 그대로) 차례대로 이은 뒤 접어서 확인하기',ARRAY['6수03-05']::text[],6),
('M5-2-u3-C7','math',5,2,'u3',7,'점대칭도형과 대칭의 중심 — 한 점을 중심으로 반 바퀴(180°) 돌렸을 때 완전히 겹치는 도형과 그 점(대칭의 중심, 언제나 하나)을 알고, 가운데에 점이 있다고 점대칭도형인 것은 아니며 접기와 돌리기를 모두 해 보아야 도형을 가를 수 있음을 알기',ARRAY['6수03-05']::text[],7),
('M5-2-u3-C8','math',5,2,'u3',8,'점대칭도형의 성질 — 반 바퀴 돌려 겹치는 대응점·대응변·대응각을 찾고, 대응변의 길이와 대응각의 크기가 같으며 대응점을 이은 선분은 모두 대칭의 중심을 지나고 중심이 그 선분을 이등분함(수직은 아님)을 알기',ARRAY['6수03-05']::text[],8),
('M5-2-u3-C9','math',5,2,'u3',9,'점대칭도형 그리기 — 꼭짓점에서 대칭의 중심까지 간 만큼(가로·세로 칸 수)을 세어 중심을 지나 반대쪽으로 같은 만큼 더 간 자리에 대응점을 찍고 차례대로 이은 뒤 반 바퀴 돌려 확인하기',ARRAY['6수03-05']::text[],9),
('M5-2-u3-C10','math',5,2,'u3',10,'문제 해결 — 땅을 합동인 도형 몇 개로 나눌 때 나눗셈으로 한 조각의 칸 수를 먼저 정하고, 조각들이 서로 합동인지와 조건(나무가 한 그루씩)을 모두 확인하며 「똑같이 나눈다」는 넓이가 같은 것이 아니라 합동이라는 뜻임을 알기',ARRAY['6수03-03']::text[],10)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M5-2-u3-X01','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2']::text[],'도형을 밀거나 뒤집거나 돌리면 변의 길이·각의 크기·넓이가 달라진다고 여긴다','움직여도 모양과 크기는 그대로'),
('M5-2-u3-X02','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2','M5-2-u3-C10']::text[],'포개거나 재어 보지 않고 겉보기(색·자리·대강의 모양)로 같은 도형인지 판단한다','포개어 보거나 재어 보기'),
('M5-2-u3-X03','math',5,'u3',ARRAY['M5-2-u3-C2','M5-2-u3-C3']::text[],'모양만 같으면 크기가 달라도 합동이라고 여긴다','크기까지 같아야 합동'),
('M5-2-u3-X04','math',5,'u3',ARRAY['M5-2-u3-C2']::text[],'뒤집거나 돌려야 겹치는 두 도형은 합동이 아니라고 여긴다','뒤집거나 돌려서 겹쳐도 합동'),
('M5-2-u3-X05','math',5,'u3',ARRAY['M5-2-u3-C2','M5-2-u3-C10']::text[],'넓이나 둘레가 같으면 합동이라고 여긴다','넓이가 같아도 겹치지 않으면 아니에요'),
('M5-2-u3-X06','math',5,'u3',ARRAY['M5-2-u3-C3','M5-2-u3-C5','M5-2-u3-C8']::text[],'대응점을 겹치는 자리가 아니라 이름 차례나 놓인 자리(왼쪽·위쪽)로 짝짓는다','겹치는 자리끼리 짝'),
('M5-2-u3-X07','math',5,'u3',ARRAY['M5-2-u3-C3','M5-2-u3-C5','M5-2-u3-C8']::text[],'대응변·대응각을 이웃한 다른 변·각과 헷갈리거나, 대응각의 크기가 다르다고 여긴다','대응변·대응각은 크기가 같아요'),
('M5-2-u3-X08','math',5,'u3',ARRAY['M5-2-u3-C4']::text[],'대칭축의 개수를 잘못 센다(대각선 대칭축을 빠뜨리거나 대칭축이 아닌 선까지 센다)','접어서 겹치는 선만 세기'),
('M5-2-u3-X09','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C7']::text[],'도형을 넓이가 같은 둘로 나누는 선은 모두 대칭축이라고 여긴다(직사각형의 대각선 등)','반으로 나누기 ≠ 접어서 겹치기'),
('M5-2-u3-X10','math',5,'u3',ARRAY['M5-2-u3-C5','M5-2-u3-C6','M5-2-u3-C8','M5-2-u3-C9']::text[],'대칭축·대칭의 중심까지의 거리와 대응점 사이의 거리를 헷갈린다(두 배와 절반을 바꾼다)','한쪽 거리 × 2 = 대응점 사이'),
('M5-2-u3-X11','math',5,'u3',ARRAY['M5-2-u3-C5','M5-2-u3-C6']::text[],'대칭축이 대응점을 이은 선분과 수직으로 만나 똑같이 둘로 나누는 것을 모른다','대칭축은 수직이등분'),
('M5-2-u3-X12','math',5,'u3',ARRAY['M5-2-u3-C6']::text[],'선대칭도형을 그릴 때 대칭축과 수직인 방향이 아닌 쪽으로 가거나 칸 수를 잘못 세고, 대칭축 위의 점을 옮긴다','수직으로 같은 칸 수만큼'),
('M5-2-u3-X13','math',5,'u3',ARRAY['M5-2-u3-C9']::text[],'점대칭도형을 그릴 때 중심까지만 가거나 중심을 지나지 않는 방향으로 대응점을 찍는다','중심을 지나 같은 만큼 더'),
('M5-2-u3-X14','math',5,'u3',ARRAY['M5-2-u3-C7']::text[],'가운데에 점이 있으면 점대칭도형이라고 여기거나, 반 바퀴가 아닌 만큼 돌려서 판단한다','반 바퀴 돌려 겹치는지'),
('M5-2-u3-X15','math',5,'u3',ARRAY['M5-2-u3-C4','M5-2-u3-C5','M5-2-u3-C7','M5-2-u3-C8','M5-2-u3-C9']::text[],'선대칭과 점대칭을 섞는다 — 접기와 돌리기, 대칭축과 대칭의 중심, 수직이등분과 이등분을 바꿔 말한다','선대칭은 접기, 점대칭은 돌리기'),
('M5-2-u3-X16','math',5,'u3',ARRAY['M5-2-u3-C10']::text[],'문제 해결에서 조건 하나만 보고(칸 수만, 나무 자리는 빼고) 나누거나 나눗셈으로 한 조각의 칸 수를 구하지 못한다','칸 수 정하기 → 두 조건 확인'),
('M5-2-u3-X17','math',5,'u3',ARRAY['M5-2-u3-C1','M5-2-u3-C2','M5-2-u3-C3','M5-2-u3-C4','M5-2-u3-C5','M5-2-u3-C6','M5-2-u3-C7','M5-2-u3-C8','M5-2-u3-C9','M5-2-u3-C10']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 아닌↔인, 틀린↔알맞은, 대응점↔대응변','물음의 「아닌·틀린」에 동그라미')
